340	
341	        /// <summary>
342	        /// An hour of living: the stomach empties (faster when working hard), and nourishment
343	        /// follows whether there's food in it. Infants live on their mother's milk, or another
344	        /// nursing woman's.
345	        /// </summary>
346	        void Metabolize(Person p)
347	        {
348	            double age = p.AgeYears(Clock);
349	            double effort = p.Current switch
350	            {
351	                Sleep _ => 0.7, Rest _ => 0.8, Socialize _ => 0.9, Eat _ => 0.9,
352	                Hunt _ => 1.6, Forage _ => 1.2, Fish _ => 1.1, Trap _ => 1.1, GatherFlint _ => 1.3, GatherWood _ => 1.3, _ => 1.0,
353	            };
354	            // Burn from the stomach first, then from the body's reserves.
355	            double burn = effort / 24;
356	            double fromStomach = Math.Min(p.Stomach, burn);
357	            p.Stomach -= fromStomach;
358	            p.Reserve = Math.Max(0, p.Reserve - (burn - fromStomach));
359	            // A well-filled stomach slowly lays down reserves, up to what this body can carry.
360	            double maxReserve = Physiology.MaxReserve(p, age);
361	            if (p.Stomach > 0.5 && p.Reserve < maxReserve)
362	            {
363	                double store = Math.Min(0.02, p.Stomach - 0.5);
364	                p.Stomach -= store;
365	                p.Reserve += store;
366	            }
367	            if (age >= 2)
368	            {
369	                p.Satiety = Physiology.Nourishment(p, age);
370	                return;
371	            }
372	            {
373	                var nurse = p.Mother != null && p.Mother.Alive && Band.Members.Contains(p.Mother) ? p.Mother
374	                    : Band.Members.FirstOrDefault(w => w.Sex == Sex.Female && w.Children.Any(c => c != p && c.Alive && c.AgeYears(Clock) < 2));
375	                // A nursing mother keeps her milk up by drawing on her own body; it only fails when she's badly starved.
376	                double milk = nurse == null ? 0 : Math.Min(1, nurse.Satiety / 0.4);
377	                double own = Physiology.Nourishment(p, age);
378	                bool softFood = p.Home != null && p.Home.SoftFoodUntil >= Clock.Day;
379	                double fed = age < 1 ? milk : softFood ? Math.Max(milk, own) : (milk + own) / 2;
380	                p.Satiety += (fed - p.Satiety) * 0.02;
381	            }
382	        }
383	
384	        /// <summary>
385	        /// Walking hours for a distance in cells. Deep winter snow slows everyone down, unless they
386	        /// have snowshoes.
387	        /// </summary>
388	        public int TravelHours(double cells, Person p)
389	        {
390	            int hours = WorldMap.TravelHours(cells);
391	            bool snow = Clock.Season == Season.Winter && World.Climate.TemperatureC(Season.Winter) < 0;
392	            if (snow && !p.Knows.Contains("hide.snowshoe")) hours = (int)Math.Ceiling(hours * 1.5);
393	            // Shoes spare the feet on long walks over rough or frozen ground.
394	            if (p.Knows.Contains("hide.shoe")) hours = Math.Max(0, (int)Math.Round(hours * 0.9));
395	            return hours;
396	        }
397	
398	        /// <summary>Rations a day this person needs: by age and size, more when pregnant or nursing.</summary>
399	        public double DailyNeed(Person p)
400	        {
401	            double age = p.AgeYears(Clock);
402	            if (age < 1) return 0;
403	            double need = age < 2 ? 0.1 : age < 14 ? 0.2 + 0.3 * age / 14 : 0.5;
404	            if (p.DueDay >= 0) need += 0.1;
405	            if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 2)) need += 0.15;
406	            // Bigger bodies eat more; so does a strong immune system, which is why immunity doesn't simply max out.
407	            return need * 2 * (0.85 + 0.3 * p.B(BodyTrait.Build) * p.B(BodyTrait.Height)) * (1 + 0.15 * (p.B(BodyTrait.Immunity) - 0.5));
408	        }
409	
410	        /// <summary>
411	        /// A day in a body. Each harm is booked against its cause, so a death is always explained
412	        /// by what actually wore the person down.
413	        /// </summary>
414	        void DailyBody(Person p, double temp)
415	        {
416	            double age = p.AgeYears(Clock);
417	            // Each harm is booked against its cause in a ledger that fades over a few weeks, so a death
418	            // is attributed to whatever really wore the person down, not just the last day's blow.
419	            foreach (var key in p.HarmLedger.Keys.ToList()) p.HarmLedger[key] *= 0.93;
420	            var harm = p.HarmLedger;
421	            void Hurt(string cause, double amount)
422	            {
423	                if (amount <= 0) return;
424	                p.Health -= amount;
425	                harm[cause] = (harm.TryGetValue(cause, out var h) ? h : 0) + amount;
426	            }
427	
428	            // Outright starvation only when the body's reserves are all but gone. Before that,
429	            // short rations do their damage by weakening people against sickness.
430	            // Wasting does its damage while the body is going without, not while someone thin is eating again.
431	            if (p.Satiety < 0.15 && p.Stomach < 0.3) Hurt("starvation", (0.15 - p.Satiety) * 0.2);
432	            // Going hungry makes people care more about food; a wound, more about safety.
433	            if (p.Satiety < 0.4) p.Shift(Drive.Food, 0.0005);
434	            if (p.Injury > 0.3) p.Shift(Drive.Safety, 0.0005);
435	            // Over months, people settle back toward who they are.
436	            for (int i = 0; i < p.Drives.Length; i++) p.Drives[i] += (p.BaseDrives[i] - p.Drives[i]) * 0.003;
437	
438	            double cold = Math.Max(0, (Shelter.ComfortTemp(Band, p) - temp) / 20.0 - p.B(BodyTrait.ColdTolerance) * 0.3 - p.B(BodyTrait.Build) * 0.1);
439	            if (age < 5 || age > 60) cold *= 1.5;
440	            // Sleeping close to family shares body heat; small children sleep against their parents.
441	            if (HasSleepingFamily(p)) cold *= 0.6;
442	            p.ColdStress = cold;
443	            // Cold mostly kills by weakening people against sickness; it freezes outright only when severe.
444	            Hurt("cold", Math.Max(0, cold - 0.3) * 0.05);
445	
446	            Infection(p, age, cold);
447	            if (p.Illness != null)
448	            {
449	                // The body's response builds over the days of a sickness, so most illnesses peak and pass.
450	                var d = p.Illness;
451	                p.SickDays++;
452	                // Care and rest help the body fight; they can't fight for it.
453	                double fight = Physiology.ImmuneStrength(p, age) * 0.08 * (1 + p.SickDays * 0.15)
454	                               * (1 + 0.5 * Math.Min(4, p.CareToday) / 4 + (p.Current is Rest || p.Current is Sleep ? 0.25 : 0));
455	                p.Sickness += d.Growth * (age < 5 ? d.ChildRisk : 1) - fight;
456	                if (p.Sickness <= 0)
457	                {
458	                    p.Sickness = 0; p.Illness = null; p.SickDays = 0;
459	                    if (d.ImmunityGain > 0) p.Immunities[d] = Math.Max(p.ImmunityTo(d), d.ImmunityGain);
460	                }
461	                else Hurt(d.DiedOf, p.Sickness * d.Harm * (age < 5 ? d.ChildRisk : 1));
462	            }
463	            foreach (var d in p.Immunities.Keys.ToList()) p.Immunities[d] = Math.Max(0, p.Immunities[d] - d.ImmunityFade);
464	
465	            p.Injury = Math.Max(0, p.Injury - 0.01 * (0.5 + p.B(BodyTrait.Endurance)));
466	            if (p.Satiety >= 0.35 && p.Sickness == 0) p.Health += 0.01 * (age > 50 ? 0.6 : 1);
467	            p.Health = Math.Min(p.Health, Physiology.MaxHealth(age) - p.Injury * 0.5);
468	
469	            // People remember the worst of the lean months (winter into spring, until the land greens),
470	            // not the average. The memory spreads like any belief and drives autumn stockpiling.
471	            if (Clock.Season == Season.Winter || Clock.Season == Season.Spring) p.WinterLow = Math.Min(p.WinterLow, p.Satiety);
472	            if (Clock.Season == Season.Summer && Clock.DayOfSeason == 20 && age >= 10)
473	            {
474	                // A hard lean season is unforgettable: the lesson lands at once, hardest on the less resilient.
475	                p.Expect.Absorb("lean:season", 1 - p.WinterLow, 0.3 + 0.3 * (1 - p.M(MindTrait.Resilience)), 0.2);
476	                p.WinterLow = 1;
477	            }
478	
479	            p.CareToday = 0;
480	            p.Fatigue *= 0.9;
481	            if (!p.Restless && age >= 20 && Rng.Chance(Crowding(p) * 0.02)) p.Restless = true;
482	            if (age < 12) DriftTowardParents(p);
483	
484	            if (p.Health > 0) return;
485	            string cause = harm.Count == 0 ? (p.Injury > 0.5 ? "wounds" : "old age") : harm.OrderByDescending(kv => kv.Value).First().Key;
486	            var weakened = new List<string>();
487	            if (Environment.GetEnvironmentVariable("ANTHRO_DEBUG_DEATHS") != null)
488	                Console.Error.WriteLine($"DEATH {p.Name} age {age:F1} {Clock.Season} cause {cause} | ledger {string.Join(", ", harm.Select(kv => $"{kv.Key} {kv.Value:F2}"))} | reserve {p.Reserve:F2} stomach {p.Stomach:F2} home food {p.Home?.Food.Total ?? 0:F1} camp food {Band.FoodTotal:F0} for {Band.Members.Count} | sick {p.Illness?.Name ?? "-"} | doing {p.Current} | expect forage {p.Expect.Get(Verb.Forage, 0):F2} hunt {p.Expect.Get(Verb.Hunt, 0):F2} | home size {p.Home?.Members.Count ?? 0} fuel {p.Home?.Fuel ?? 0:F1}");
489	            if (cause != "starvation" && p.Satiety < 0.5) weakened.Add("hunger");
490	            if (cause != "cold" && p.ColdStress > 0.15) weakened.Add("cold");
491	            if (Physiology.MaxHealth(age) < 0.3 && cause != "old age") weakened.Add("age");
492	            Kill(p, cause, weakened.Count == 0 ? null : "weakened by " + string.Join(" and ", weakened));
493	        }
494	
495	        /// <summary>
496	        /// Sickness always comes from somewhere that isn't another person: a fouled camp, rotten
497	        /// meat, an open wound, or (for someone already sick) a winter chill settling in the lungs.
498	        /// Catching diseases from people happens through <see cref="Contact"/>.
499	        /// </summary>
500	        /// <summary>
501	        /// Calibration (fitted to forager child mortality, ~20% before 1 and ~45% before 15): the
502	        /// daily chance a sickness settles in the chest before cold is counted, and how much likelier
503	        /// gut infections are in the weaning years.
504	        /// </summary>
505	        public static double ChestRisk = 0.005, WeaningRisk = 6;
506	
507	        /// <summary>
508	        /// Calibration (fitted to forager mortality: accidents ~5-10% of deaths, ~1-2 adult deaths
509	        /// per 1,000 a year): chance per hour out on the land of a serious accident.
510	        /// </summary>
511	        public static double AccidentRate = 1e-5;
512	
513	        /// <summary>
514	        /// Out on the land, things go wrong now and then: a fall, a bad cut, a slip into cold water.
515	        /// Most are wounds that heal (or fester); some kill.
516	        /// </summary>
517	        void MaybeAccident(Person p)
518	        {
519	            var a = p.Current;
520	            bool water = a is Fish;
521	            if (!(a is Forage || a is Hunt || a is Fish || a is Trap || a is GatherWood || a is GatherFlint || a is Visit)) return;
522	            if (!Rng.Chance(AccidentRate * (a is Hunt ? 2 : 1))) return;
523	            p.Injury = Inheritance.Clamp01(p.Injury + Rng.Range(0.3, 1.2));
524	            if (p.Injury >= 0.95) Kill(p, water ? "drowning" : "a fall");
525	            else Chronicle.Write(Clock, Importance.Detail, $"{p.Name} was badly hurt in {(water ? "the river" : "a fall")}.");
526	        }
527	
528	        /// <summary>Calibration: daily chance of catching a fever from insects or water (warm-season peak).</summary>
529	        public static double FeverRate = 0.0003;
530	
531	        void Infection(Person p, double age, double coldStress)
532	        {
533	            double immune = Physiology.ImmuneStrength(p, age);
534	            // A breastfed baby in its first months carries its mother's protection, from her milk.
535	            var mother = p.Mother;
536	            bool nursed = age < 0.5 && mother != null && mother.Alive && Band.Members.Contains(mother);
537	            double Protected(Disease d) => Math.Max(p.ImmunityTo(d), nursed ? mother!.ImmunityTo(d) * 0.8 : 0);
538	            if (p.Illness != null)
539	            {
540	                // Another sickness can settle in the lungs: most often in babies and the old, and far
541	                // more when they're chilled. What winter kills the old with, and small children all year.
542	                double frail = age < 2 ? 3 : age < 5 ? 1.5 : age > 60 ? 2 : 1;
543	                if (p.Illness != Disease.LungSickness && Rng.Chance((ChestRisk + coldStress * 0.05) * frail * (1.3 - immune)))
544	                {
545	                    p.Illness = Disease.LungSickness;
546	                    p.Sickness = Math.Max(p.Sickness, 0.3);
547	                    p.SickDays = 0;
548	                }
549	                return;
550	            }
551	            double weak = 1.3 - immune;
552	            // Colds are always around in any human group, and spread more when people huddle in winter.
553	            double coldSeason = Clock.Season == Season.Winter ? 3 : Clock.Season == Season.Autumn ? 1.5 : 1;
554	            // Small children catch everything going: their bodies haven't met these germs yet.
555	            double young = age < 5 ? 2.5 : age < 14 ? 1.5 : 1;
556	            if (Rng.Chance(0.004 * coldSeason * young * weak * (1 - Protected(Disease.Cold)))) { p.Catch(Disease.Cold, Rng.Range(0.1, 0.3)); return; }
557	            // Gut infections are always around for small children, from dirt and, worst of all, from
558	            // the first foods other than milk: the weaning years are the most dangerous of childhood.
559	            double weaning = age >= 0.5 && age < 3 ? WeaningRisk : 1;
560	            if (age < 5 && Rng.Chance(0.0015 * weaning * weak * (1 - Protected(Disease.Flux)))) { p.Catch(Disease.Flux, Rng.Range(0.1, 0.3)); return; }
561	            // Fevers carried by insects and water turn up now and then, more in the warm months.
562	            double warm = Clock.Season == Season.Summer ? 2 : Clock.Season == Season.Winter ? 0.2 : 1;
563	            if (Rng.Chance(FeverRate * warm * young * weak * (1 - Protected(Disease.Fever)))) { p.Catch(Disease.Fever, Rng.Range(0.15, 0.35)); return; }
564	            if (p.AteRotten && Rng.Chance(0.3 * weak)) { p.Catch(Disease.BadMeat, Rng.Range(0.15, 0.35)); return; }
565	            if (p.Injury > 0.2 && Rng.Chance(p.Injury * 0.03 * weak)) { p.Catch(Disease.WoundRot, Rng.Range(0.2, 0.4)); return; }
566	            double filth = Band.Filth * 0.0004 * (age < 5 ? 2 : 1);
567	            if (Rng.Chance(filth * weak * (1 - Protected(Disease.Flux)))) p.Catch(Disease.Flux, Rng.Range(0.15, 0.4));
568	        }
569	
570	        /// <summary>
571	        /// Close contact between two people for some hours: a contagious illness may pass either way,
572	        /// depending on how sick the carrier is and how well the other resists.
573	        /// </summary>
574	        public void Contact(Person a, Person b, double hours)
575	        {
576	            Pass(a, b, hours);
577	            Pass(b, a, hours);
578	        }
579	
580	        void Pass(Person from, Person to, double hours)
581	        {
582	            var d = from.Illness;
583	            if (d == null || d.Contagion <= 0 || to.Illness != null || !to.Alive) return;
584	            double resist = Physiology.ImmuneStrength(to, to.AgeYears(Clock));
585	            double chance = d.Contagion * from.Sickness * hours * (1.3 - resist) * (1 - to.ImmunityTo(d));
586	            if (Rng.Chance(chance)) to.Catch(d, Rng.Range(0.1, 0.3));
587	        }
588	
589	        /// <summary>Whether someone is in camp tonight (not off visiting another band).</summary>
590	        bool Home(Person p) => !(p.Current is Visit) && Band.Members.Contains(p);
591	
592	        bool HasSleepingFamily(Person p) =>
593	            !(p.Current is Visit) &&
594	            ((p.Partner != null && Home(p.Partner))
595	            || p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 14 && Home(c))
596	            || (p.AgeYears(Clock) < 14 && ((p.Mother != null && Home(p.Mother)) || (p.Father != null && Home(p.Father)))));
597	
598	        /// <summary>Families sleep together: a night is many hours of close contact.</summary>
599	        void SleepingTogether()
600	        {
601	            foreach (var p in Band.Members)
602	            {
603	                if (p.Current is Visit) continue;
604	                if (p.Partner != null && p.Partner.Id > p.Id && Home(p.Partner))
605	                {
606	                    Contact(p, p.Partner, 3);
607	                    // Sharing a hearth and a bed keeps a couple's bond alive.
608	                    p.AddAffinity(p.Partner, 0.004); p.Partner.AddAffinity(p, 0.004);
609	                }
610	                foreach (var c in p.Children)
611	                    if (c.Alive && c.AgeYears(Clock) < 14 && Home(c)) Contact(p, c, 2);
612	            }
613	        }
614	
615	        /// <summary>Children's interests lean toward whoever raises them.</summary>
616	        static void DriftTowardParents(Person child)
617	        {
618	            foreach (var parent in new[] { child.Mother, child.Father })
619	            {
620	                if (parent == null || !parent.Alive) continue;
621	                for (int i = 0; i < child.Interests.Length; i++)
622	                    child.Interests[i] += (parent.Interests[i] - child.Interests[i]) * 0.002;
623	            }
624	        }
625	
626	        public void Kill(Person p, string cause, string? weakenedBy = null)
627	        {
628	            if (!p.Alive) return;
629	            double age = p.AgeYears(Clock);
630	            p.Alive = false;
631	            p.DeathCause = cause;
632	            p.DeathDay = Clock.Day;
633	            Band.LastDeathDay = Clock.Day;
634	            // Losing family makes people hold the rest closer.
635	            foreach (var kin in Band.Members) if (kin.IsKin(p)) kin.Shift(Drive.Family, 0.01);
636	            // Laying the dead to rest eases the grief of those left (less of it turns to discontent).
637	            if (Band.AnyoneKnows("burial.cover"))
638	                foreach (var m in Band.Members) m.Discontent *= Band.AnyoneKnows("burial.goods") ? 0.9 : 0.95;
639	            LeaveHousehold(p);
640	            Band.Members.Remove(p);
641	            Band.Dead.Add(p);
642	            if (p.Partner != null) { p.Partner.Partner = null; p.Partner = null; }
643	            ThisYear.Deaths[cause] = ThisYear.Deaths.TryGetValue(cause, out var n) ? n + 1 : 1;
644	
645	            string what = cause.StartsWith("killed") || cause.StartsWith("trampled") || cause.StartsWith("gored") ? $"was {cause}" : $"died of {cause}";
646	            WitnessDeath(p, cause);
647	            if (cause.StartsWith("starvation"))
648	            {
649	            }
650	            string who = p.BigKills >= 5 ? $"{p.Name}, one of the band's great hunters," : p.Name;
651	            Chronicle.Write(Clock, age < 5 ? Importance.Detail : Importance.Notable, $"{who} {what} at {(int)age}{(weakenedBy == null ? "" : ", " + weakenedBy)}.");
652	
653	            foreach (var stage in p.Knows)
654	                if (!Band.AnyoneKnows(stage) && Web != null && Web.Stages.TryGetValue(stage, out var s) && !s.Known)
655	                    Chronicle.Write(Clock, Importance.Major, $"When {p.Name} died, the band lost {s.Name.ToLower()}.");
656	
657	            if (Band.Members.Count == 0)
658	                Chronicle.Write(Clock, Importance.Major, $"With {p.Name}'s death, the {Band.Name} band is gone.");
659	        }
660	
661	        /// <summary>
662	        /// Everyone hears how someone died. A death by an animal teaches the whole band to fear it,
663	        /// hardest for those who loved the dead.
664	        /// </summary>
665	        void WitnessDeath(Person dead, string cause)
666	        {
667	            var sp = Species.All.FirstOrDefault(s => cause.EndsWith(" " + s.Name));
668	            if (sp == null) return;
669	            foreach (var p in Band.Members)
670	                p.Expect.LearnDanger(p, sp.Name, 1, HuntParty.InstinctiveDanger(sp), 0.3 + p.GetAffinity(dead));
671	        }
672	
673	        // ---- Families ------------------------------------------------------------------------
674	
675	        /// <summary>
676	        /// Whether a couple conceives today. Ovulation follows the mother's energy balance: well-fed
677	        /// women conceive readily, thin ones rarely (this is how lean times lower births among real
678	        /// foragers). Nursing suppresses it, strongly at first and fading as the child weans over its
679	        /// first four years, which spaces births about four years apart.
680	        /// </summary>
681	        void MaybeConceive(Person p)
