1	using System.Diagnostics;
2	using Anthro.Runner;
3	using Anthro.Sim;
4	using Anthro.Sim.Core;
5	using Anthro.Sim.Ecology;
6	
7	// Usage: dotnet run --project Anthro.Runner -- [--seed N] [--years N] [--detail] [--quiet]
8	Console.OutputEncoding = System.Text.Encoding.UTF8;
9	ulong seed = 1;
10	int years = 100;
11	bool detail = false, quiet = false, families = false, kids = false, allBands = false;
12	string[] grant = Array.Empty<string>();
13	for (int i = 0; i < args.Length; i++)
14	{
15	    switch (args[i])
16	    {
17	        case "--seed": seed = ulong.Parse(args[++i]); break;
18	        case "--years": years = int.Parse(args[++i]); break;
19	        case "--detail": detail = true; break;
20	        case "--quiet": quiet = true; break;
21	        case "--families": families = true; break;
22	        case "--kids": kids = true; break;
23	        case "--grant": grant = args[++i].Split(',', StringSplitOptions.RemoveEmptyEntries); break;
24	        case "--all": allBands = true; break;
25	        case "--profile": Anthro.Sim.Core.Profiler.Enabled = true; break;
26	        // Testing only: land richness for calibration sweeps.
27	        case "--chest": Anthro.Sim.Simulation.ChestRisk = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
28	        case "--weaning": Anthro.Sim.Simulation.WeaningRisk = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
29	        case "--fever": Anthro.Sim.Simulation.FeverRate = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
30	        case "--discovery": Anthro.Sim.Simulation.DiscoveryRate = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
31	        case "--accident": Anthro.Sim.Simulation.AccidentRate = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
32	        case "--plants": Anthro.Sim.World.WorldGen.PlantDensity = double.Parse(args[++i], System.Globalization.CultureInfo.InvariantCulture); break;
33	    }
34	}
35	
36	var webPath = WebLoader.Find();
37	var web = webPath != null ? WebLoader.Load(webPath) : null;
38	if (web == null) Console.WriteLine("(discovery-web.json not found; running with built-in starting knowledge)");
39	else
40	{
41	    var problems = web.Validate().ToList();
42	    Console.WriteLine($"Discovery web: {web.Tiles.Count} skills, {web.Stages.Count} stages, {web.KnownAtStart.Count()} known at start.");
43	    foreach (var p in problems) Console.WriteLine($"  ! {p}");
44	}
45	
46	var region = Region.Create(seed, web);
47	var sim = region.Founders;
48	// Testing only: hand everyone on the map some knowledge, to see what a technology does before discovery exists.
49	foreach (var m in region.People) foreach (var g in grant) m.Knows.Add(g);
50	if (grant.Length > 0) Console.WriteLine($"Granted: {string.Join(", ", grant)}");
51	Console.WriteLine($"Seed {seed}. Running {years} years.\n");
52	
53	// The story follows the founding band; the region's own events (animals, bands appearing and ending) are shown too.
54	foreach (var b in region.Bands) foreach (var e in b.Chronicle.Entries) Console.WriteLine($"  ■ Y{e.Year,-3} {e.Season,-6} {e.Text}");
55	if (!quiet)
56	{
57	    void Show(ChronicleEntry e)
58	    {
59	        if (e.Importance == Importance.Detail && !detail) return;
60	        string mark = e.Importance == Importance.Major ? "■" : "·";
61	        Console.WriteLine($"  {mark} Y{e.Year,-3} {e.Season,-6} {e.Text}");
62	    }
63	    sim.Chronicle.Written += Show;
64	    region.Chronicle.Written += Show;
65	    // Every band's story, labelled, including bands formed later.
66	    if (allBands)
67	    {
68	        var watched = new HashSet<Simulation> { sim };
69	        void Watch()
70	        {
71	            foreach (var b in region.Bands.Where(b => watched.Add(b)))
72	            {
73	                var band = b;
74	                band.Chronicle.Written += e =>
75	                {
76	                    if (e.Importance == Importance.Detail && !detail) return;
77	                    Console.WriteLine($"  {(e.Importance == Importance.Major ? "■" : "·")} Y{e.Year,-3} {e.Season,-6} [{band.Band.Name}] {e.Text}");
78	                };
79	            }
80	        }
81	        Watch();
82	        region.Chronicle.Written += _ => Watch();
83	        region.YearEnded += _ => Watch();
84	    }
85	}
86	
87	sim.YearEnded += y =>
88	{
89	    if (kids) foreach (var c in sim.Band.Members.Where(m => m.AgeYears(sim.Clock) >= 2 && m.AgeYears(sim.Clock) < 15)) Console.WriteLine($"     kid {c.Name,-8} age {c.AgeYears(sim.Clock),4:F1} stomach {c.Stomach:F2} reserve {c.Reserve:F2} fed {c.Satiety:F2} health {c.Health:F2} doing {c.Current}");
90	    if (families) Console.WriteLine($"     food: needed {y.Needed:F0} gathered {y.Gathered:F0} hunted {y.Hunted:F0} fished {y.Fished:F0} eaten-at-camp {y.Eaten:F0} spoiled {y.Spoiled:F0} | adult hours: " + string.Join(", ", y.Hours.OrderByDescending(h => h.Value).Select(h => $"{h.Key} {h.Value}")));
91	    if (families)
92	        foreach (var w in sim.Band.Members.Where(m => m.Sex == Anthro.Sim.People.Sex.Female && m.AgeYears(sim.Clock) >= 14))
93	            Console.WriteLine($"     {w.Name,-8} age {w.AgeYears(sim.Clock),4:F0} partner {(w.Partner?.Name ?? "-"),-8} fed {w.Satiety:F2} health {w.Health:F2} due {w.DueDay} kids<2 {w.Children.Count(c => c.Alive && c.AgeYears(sim.Clock) < 2)}");
94	    string deaths = y.Deaths.Count == 0 ? "none" : string.Join(", ", y.Deaths.Select(d => $"{d.Value} {d.Key}"));
95	    string kills = y.Kills.Count == 0 ? "none" : string.Join(", ", y.Kills.OrderByDescending(k => k.Value).Select(k => $"{k.Value} {k.Key}"));
96	    Console.WriteLine($"── Year {y.Year,3} │ pop {y.Population,3} │ couples {y.Couples,2} │ fed {y.AvgSatiety:P0} health {y.AvgHealth:P0} sick-days {y.SickDays,4} │ standing {y.Valor:F2} give {y.Sharing:F1} │ shared {y.Shared,4:F0} refused {y.Refusals,3} thefts {y.Thefts,2} fights {y.Fights,2} raids {y.Raids} │ born {y.Births,2} │ cook+{y.CookingGain,4:F0} fire-out {y.FireOutDays,3} │ died: {deaths} │ kills: {kills} │ "
97	                      + $"region: deer {sim.Ecology.Pool(Species.Deer).Count + sim.Ecology.Total(Species.Deer)}, mammoths {sim.Ecology.Pool(Species.Mammoth).Count + sim.Ecology.Total(Species.Mammoth)}");
98	};
99	
100	// One line a year for the whole map: every band's size, and births and deaths across all of them.
101	region.YearEnded += all =>
102	{
103	    var deaths = new Dictionary<string, int>();
104	    foreach (var (_, y) in all) foreach (var d in y.Deaths) deaths[d.Key] = deaths.TryGetValue(d.Key, out var n) ? n + d.Value : d.Value;
105	    string died = deaths.Count == 0 ? "none" : string.Join(", ", deaths.OrderByDescending(d => d.Value).Select(d => $"{d.Value} {d.Key}"));
106	    string bands = string.Join(", ", region.Bands.OrderByDescending(b => b.Band.Members.Count).Select(b => $"{b.Band.Name} {b.Band.Members.Count}"));
107	    Console.WriteLine($"   map │ total {region.People.Count(),3} │ bands {region.Bands.Count}: {bands} │ born {all.Sum(a => a.year.Births)} │ died: {died}");
108	};
109	
110	var timer = Stopwatch.StartNew();
111	region.RunYears(years);
112	timer.Stop();
113	
114	Console.WriteLine();
115	Console.WriteLine(region.Extinct
116	    ? $"Everyone on the map was gone by year {region.Clock.Year}."
117	    : $"After {region.Clock.Year} years: {region.People.Count()} people alive in {region.Bands.Count} bands; the founding band {(sim.Extinct ? "is gone" : $"has {sim.Band.Members.Count}")}.");
118	// Child mortality, the figure real forager demography is most often summarized by: of the children
119	// born early enough that we know whether they reached 15, how many died as infants and as children.
120	{
121	    var everyone = region.AllBands.SelectMany(b => b.Band.Members.Concat(b.Band.Dead)).Distinct().ToList();
122	    long cutoff = (long)(region.Clock.Year - 15) * Anthro.Sim.Core.SimClock.DaysPerYear;
123	    var cohort = everyone.Where(p => p.BirthDay >= 0 && p.BirthDay <= cutoff).ToList();
124	    double AgeAtDeath(Anthro.Sim.People.Person p) => (p.DeathDay - p.BirthDay) / (double)Anthro.Sim.Core.SimClock.DaysPerYear;
125	    if (cohort.Count > 0)
126	    {
127	        double infant = cohort.Count(p => !p.Alive && AgeAtDeath(p) < 1) / (double)cohort.Count;
128	        double child = cohort.Count(p => !p.Alive && AgeAtDeath(p) < 15) / (double)cohort.Count;
129	        Console.WriteLine($"Children born in years 0-{region.Clock.Year - 15} ({cohort.Count}): died before 1: {infant:P0}, before 15: {child:P0}.");
130	    }
131	    var adults = everyone.Where(p => !p.Alive && AgeAtDeath(p) >= 15).ToList();
132	    if (adults.Count > 0) Console.WriteLine($"Adults who died ({adults.Count}): mean age {adults.Average(AgeAtDeath):F0}.");
133	}
134	// What was discovered, and what's still known now.
135	{
136	    var firsts = region.DiscoveryLog.GroupBy(d => d.stage).Select(g => g.OrderBy(d => d.year).First()).OrderBy(d => d.year).ToList();
137	    var knownNow = region.People.SelectMany(p => p.Knows).Distinct().Where(id => web == null || !web.Stages[id].Known).ToList();
138	    Console.WriteLine($"Discoveries: {region.DiscoveryLog.Count} ({firsts.Count} different); known on the map now: {knownNow.Count} beyond the start.");
139	    if (firsts.Count > 0) Console.WriteLine("  first found: " + string.Join(", ", firsts.Select(d => $"{d.stage} (Y{d.year}, {d.band})")));
140	    if (knownNow.Count > 0) Console.WriteLine("  known now: " + string.Join(", ", knownNow.OrderBy(x => x)));
141	}
142	// How each of the biggest bands has come to weigh things (drive averages, 0.5 typical).
143	foreach (var b in region.Bands.OrderByDescending(b => b.Band.Members.Count).Take(5))
144	{
145	    var adults = b.Band.Members.Where(m => m.AgeYears(region.Clock) >= 16).ToList();
