        /// <summary>A hunt, a near miss or a kill frightens the herd.</summary>
        public void Startle(AnimalGroup g, double amount) => g.Fear = Math.Min(1, g.Fear + amount);

        /// <summary>Each kill teaches the region the valley is dangerous, in proportion to how many the region can spare.</summary>
        public void RecordKill(Species sp)
        {
            var pool = _pools[sp];
            pool.DangerMemory = Math.Min(0.9, pool.DangerMemory + 3.0 / Capacity(sp));
        }

        void NewYear(Region sim)
        {
            foreach (var sp in Species.All)
            {
                Breed(sim, sp);
                _pools[sp].DangerMemory *= 0.6;
                Arrive(sim, sp, quiet: false);
            }
        }

        void Breed(Region sim, Species sp)
        {
            var pool = _pools[sp];
            var local = Living(sp).ToList();
            int valley = local.Sum(g => g.Count);
            int total = pool.Count + valley;
            if (total == 0)
            {
                if (_goneFromRegion.Add(sp))
                    sim.Chronicle.Write(sim.Clock, Importance.Major, $"No {sp.Plural} are left anywhere in the region.");
                return;
            }
            int change = (int)Math.Round(total * sp.BirthRate * (1 - (double)total / Capacity(sp)));
            int toValley = valley == 0 ? 0 : (int)Math.Round(change * (double)valley / total);
            pool.Count = Math.Max(0, pool.Count + change - toValley);
            for (int i = 0; i < Math.Abs(toValley) && local.Count > 0; i++)
                local[sim.Rng.Range(0, local.Count)].Count += Math.Sign(toValley);
        }

        /// <summary>
        /// Animals come in until the valley holds its share of the region, scaled down by how
        /// dangerous the valley has proved. Arrivals are random, so lean years happen.
        /// </summary>
        void Arrive(Region sim, Species sp, bool quiet)
        {
            var pool = _pools[sp];
            int valley = Total(sp);
            double target = (pool.Count + valley) * sp.ValleyShare * (1 - pool.DangerMemory);
            double lambda = Math.Max(0, target - valley) * (sp.MigratoryFraction > 0 ? 1.0 : 0.4);
            int arrivals = Math.Min(pool.Count, sim.Rng.Poisson(lambda));
            pool.Count -= arrivals;
            while (arrivals > 0)
            {
                int size = Math.Min(arrivals, sim.Rng.Range(sp.GroupMin, sp.GroupMax + 1));
                arrivals -= size;
                var edge = sim.World[sim.Rng.Chance(0.5) ? 0 : sim.World.Size - 1, sim.Rng.Range(0, sim.World.Size)];
                var g = new AnimalGroup(_nextId++, sp, size, edge.X, edge.Y);
                if (quiet) { var c = RandomCell(sim.World, sim.Rng, sp.SummerTerrain); g.X = c.X; g.Y = c.Y; }
