var watched = new HashSet<Simulation>();
void Watch()
{
    foreach (var b in region.Bands.Where(b => watched.Add(b)))
        b.Chronicle.Written += e => { if (e.Text.Contains(" parted.")) partings++; else if (Regex.IsMatch(e.Text, @" left \w+ for ")) leftFor++; };
}
