1	using System;
2	using System.Collections.Generic;
3	using System.Linq;
4	using Anthro.Sim.Core;
5	using Anthro.Sim.World;
6	
7	namespace Anthro.Sim.Ecology
8	{
9	    /// <summary>
10	    /// The map is one part of a wider region. Every species follows the same rules:
11	    /// the whole regional population breeds toward its capacity each spring; part of it comes into
12	    /// the valley for the warm season (fewer if the valley has proved dangerous); migratory animals
13	    /// leave again in autumn. Animals killed in the valley never go back to breed, so heavy hunting
14	    /// drains the region itself, fastest for slow breeders.
15	    /// </summary>
16	    public sealed class EcologySystem
17	    {
18	        readonly List<AnimalGroup> _groups = new List<AnimalGroup>();
19	        readonly Dictionary<Species, RegionalPool> _pools = new Dictionary<Species, RegionalPool>();
20	        readonly HashSet<Species> _goneFromRegion = new HashSet<Species>();
21	        int _nextId;
22	        /// <summary>The map's area in km².</summary>
23	        double _areaKm2;
24	
25	        /// <summary>
26	        /// What the wider region can support: enough that its usual share in the map comes to the
27	        /// species' real density across the map's area.
28	        /// </summary>
29	        int Capacity(Species sp) => (int)Math.Round(sp.DensityPerKm2 * _areaKm2 / sp.ValleyShare);
30	
31	        public IReadOnlyList<AnimalGroup> Groups => _groups;
32	
33	        public RegionalPool Pool(Species sp) => _pools[sp];
34	
35	        public void Populate(Region sim)
36	        {
37	            _areaKm2 = Math.Pow(sim.World.Size * WorldMap.CellMeters / 1000, 2);
38	            // The region starts somewhat below what it could support.
39	            foreach (var sp in Species.All) _pools[sp] = new RegionalPool(sp, (int)Math.Round(Capacity(sp) * 0.65));
40	            foreach (var sp in Species.All) Arrive(sim, sp, quiet: true);
41	        }
42	
43	        public int Total(Species sp) => _groups.Where(g => g.Species == sp).Sum(g => g.Count);
44	
45	        public IEnumerable<AnimalGroup> Living(Species sp) => _groups.Where(g => g.Species == sp && !g.Gone);
46	
47	        public void DailyUpdate(Region sim)
48	        {
49	            var season = sim.Clock.Season;
50	            foreach (var g in _groups)
51	            {
52	                if (g.Gone) continue;
53	                double toCamp = NearestCamp(sim, g.X, g.Y);
54	                g.Fear = Math.Max(0, g.Fear - 0.04);
55	                if (!g.Species.Predator && toCamp < WorldMap.FromMeters(1500)) g.Fear = Math.Min(1, g.Fear + 0.03);
56	
57	                if (g.Species.Predator) FollowPrey(g);
58	                else if (WorldMap.Distance(g.X, g.Y, g.TargetX, g.TargetY) < WorldMap.FromMeters(300) || sim.Rng.Chance(0.05) || (g.Fear > 0.3 && toCamp < WorldMap.FromMeters(3000)))
59	                    ChooseRange(sim, g, season);
60	                Step(g, WorldMap.FromMeters(g.Species.Predator ? 6000 : 3000));
61	            }
62	
63	            foreach (var pack in _groups.Where(g => g.Species.Predator && !g.Gone).ToList()) PackHunts(sim, pack);
64	
65	            if (sim.Clock.DayOfYear == 0 && sim.Clock.Day > 0) NewYear(sim);
66	            if (sim.Clock.DayOfYear == (int)Season.Winter * SimClock.DaysPerSeason) Depart(sim);
67	            _groups.RemoveAll(g => g.Gone);
68	            Index();
69	        }
70	
71	        // ---- Where the animals are (for who can see them) -----------------------------------------
72	
73	        const int Bucket = 25;
74	        readonly Dictionary<int, List<AnimalGroup>> _buckets = new Dictionary<int, List<AnimalGroup>>();
75	        readonly Dictionary<int, AnimalGroup> _byId = new Dictionary<int, AnimalGroup>();
76	
77	        void Index()
78	        {
79	            _buckets.Clear(); _byId.Clear();
80	            foreach (var g in _groups)
81	            {
82	                if (g.Gone) continue;
83	                int k = (int)(g.X / Bucket) * 1000 + (int)(g.Y / Bucket);
84	                if (!_buckets.TryGetValue(k, out var list)) _buckets[k] = list = new List<AnimalGroup>();
85	                list.Add(g);
86	                _byId[g.Id] = g;
87	            }
88	        }
89	
90	        public AnimalGroup? ById(int id) => _byId.TryGetValue(id, out var g) && !g.Gone ? g : null;
91	
92	        /// <summary>Animal groups within a distance of a point (as of this morning's positions).</summary>
93	        public IEnumerable<AnimalGroup> Near(double x, double y, double radius)
94	        {
95	            if (_byId.Count == 0) Index();
96	            int bx = (int)(x / Bucket), by = (int)(y / Bucket);
97	            for (int i = bx - 1; i <= bx + 1; i++)
98	                for (int j = by - 1; j <= by + 1; j++)
99	                    if (_buckets.TryGetValue(i * 1000 + j, out var list))
100	                        foreach (var g in list)
101	                            if (!g.Gone && WorldMap.Distance(g.X, g.Y, x, y) <= radius) yield return g;
102	        }
103	
104	        /// <summary>A hunt, a near miss or a kill frightens the herd.</summary>
105	        public void Startle(AnimalGroup g, double amount) => g.Fear = Math.Min(1, g.Fear + amount);
106	
107	        /// <summary>Each kill teaches the region the valley is dangerous, in proportion to how many the region can spare.</summary>
108	        public void RecordKill(Species sp)
109	        {
110	            var pool = _pools[sp];
111	            pool.DangerMemory = Math.Min(0.9, pool.DangerMemory + 3.0 / Capacity(sp));
112	        }
113	
114	        void NewYear(Region sim)
115	        {
116	            foreach (var sp in Species.All)
117	            {
118	                Breed(sim, sp);
119	                _pools[sp].DangerMemory *= 0.6;
120	                Arrive(sim, sp, quiet: false);
121	            }
122	        }
123	
124	        void Breed(Region sim, Species sp)
125	        {
126	            var pool = _pools[sp];
127	            var local = Living(sp).ToList();
128	            int valley = local.Sum(g => g.Count);
129	            int total = pool.Count + valley;
130	            if (total == 0)
131	            {
132	                if (_goneFromRegion.Add(sp))
133	                    sim.Chronicle.Write(sim.Clock, Importance.Major, $"No {sp.Plural} are left anywhere in the region.");
134	                return;
135	            }
136	            int change = (int)Math.Round(total * sp.BirthRate * (1 - (double)total / Capacity(sp)));
137	            int toValley = valley == 0 ? 0 : (int)Math.Round(change * (double)valley / total);
138	            pool.Count = Math.Max(0, pool.Count + change - toValley);
139	            for (int i = 0; i < Math.Abs(toValley) && local.Count > 0; i++)
140	                local[sim.Rng.Range(0, local.Count)].Count += Math.Sign(toValley);
141	        }
142	
143	        /// <summary>
144	        /// Animals come in until the valley holds its share of the region, scaled down by how
145	        /// dangerous the valley has proved. Arrivals are random, so lean years happen.
146	        /// </summary>
147	        void Arrive(Region sim, Species sp, bool quiet)
148	        {
149	            var pool = _pools[sp];
150	            int valley = Total(sp);
151	            double target = (pool.Count + valley) * sp.ValleyShare * (1 - pool.DangerMemory);
152	            double lambda = Math.Max(0, target - valley) * (sp.MigratoryFraction > 0 ? 1.0 : 0.4);
153	            int arrivals = Math.Min(pool.Count, sim.Rng.Poisson(lambda));
154	            pool.Count -= arrivals;
155	            while (arrivals > 0)
156	            {
157	                int size = Math.Min(arrivals, sim.Rng.Range(sp.GroupMin, sp.GroupMax + 1));
158	                arrivals -= size;
159	                var edge = sim.World[sim.Rng.Chance(0.5) ? 0 : sim.World.Size - 1, sim.Rng.Range(0, sim.World.Size)];
160	                var g = new AnimalGroup(_nextId++, sp, size, edge.X, edge.Y);
161	                if (quiet) { var c = RandomCell(sim.World, sim.Rng, sp.SummerTerrain); g.X = c.X; g.Y = c.Y; }
162	                ChooseRange(sim, g, sim.Clock.Season);
163	                _groups.Add(g);
164	            }
165	            if (!quiet && valley == 0 && Total(sp) == 0 && pool.Count > 0 && sp.Huntable && sp.MigratoryFraction > 0)
166	                sim.Chronicle.Write(sim.Clock, Importance.Notable, $"No {sp.Plural} came into the valley this spring.");
167	        }
168	
169	        void Depart(Region sim)
170	        {
171	            foreach (var g in _groups.Where(g => !g.Gone && g.Species.MigratoryFraction > 0))
172	            {
173	                int leaving = (int)Math.Round(g.Count * g.Species.MigratoryFraction);
174	                g.Count -= leaving;
175	                _pools[g.Species].Count += leaving;
176	            }
177	        }
178	
179	        void ChooseRange(Region sim, AnimalGroup g, Season season)
180	        {
181	            var terrain = season == Season.Winter ? g.Species.WinterTerrain : g.Species.SummerTerrain;
182	            if (g.Fear <= 0.3)
183	            {
184	                var spot = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(4000), terrain);
185	                g.TargetX = spot.X; g.TargetY = spot.Y;
186	                return;
187	            }
188	            // Frightened animals pick ground well away from people.
189	            Cell best = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(6000), terrain);
190	            for (int i = 0; i < 5; i++)
191	            {
192	                var c = NearbyCell(sim.World, sim.Rng, g.X, g.Y, WorldMap.FromMeters(6000), terrain);
193	                if (NearestCamp(sim, c.X, c.Y) > NearestCamp(sim, best.X, best.Y)) best = c;
194	            }
195	            g.TargetX = best.X; g.TargetY = best.Y;
196	        }
197	
198	        void FollowPrey(AnimalGroup pack)
199	        {
200	            var prey = _groups.Where(g => !g.Gone && !g.Species.Predator && g.Species.Huntable && g.Species.Size < 4)
201	                .OrderBy(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y)).FirstOrDefault();
202	            if (prey != null) { pack.TargetX = prey.X; pack.TargetY = prey.Y; }
203	        }
204	
205	        /// <summary>Wolves hunt like people do: get close before the prey bolts. A big kill feeds the pack for days.</summary>
206	        void PackHunts(Region sim, AnimalGroup pack)
207	        {
208	            pack.Hunger = Math.Min(1.5, pack.Hunger + 0.25);
209	            if (pack.Hunger < 0.5) return;
210	            var prey = _groups.Where(g => !g.Gone && !g.Species.Predator && g.Species.Huntable && g.Species.Size < 4)
211	                .Where(g => WorldMap.Distance(g.X, g.Y, pack.X, pack.Y) < WorldMap.FromMeters(1500))
212	                .OrderByDescending(g => g.Species.Meat).FirstOrDefault();
213	            if (prey != null)
214	            {
215	                Startle(prey, 0.15);
216	                double catchChance = 0.45 * (1 - prey.FlightDistance / 120) * (pack.Species.Speed / (pack.Species.Speed + prey.Species.Speed) * 2);
217	                if (sim.Rng.Chance(catchChance))
218	                {
219	                    prey.Count--;
220	                    pack.Hunger -= Math.Min(1.3, prey.Species.Meat * 0.04 * 5 / Math.Max(1, pack.Count));
221	                }
222	            }
