4	{
5	    /// <summary>
6	    /// A species is described by what it physically is and how it lives. How hunts and populations
7	    /// turn out comes from these properties meeting people's skills and weapons, never from a
8	    /// per-species outcome number.
9	    /// </summary>
10	    public sealed class Species
11	    {
12	        public string Name = "";
13	        public string Plural = "";
14	        public int GroupMin, GroupMax;
15	
16	        // ---- Population (the valley is one corner of a wider region) ----
17	        /// <summary>
18	        /// How many live on a square kilometre of good habitat (real field densities). The map holds
19	        /// this many per km² in the warm season when nothing has frightened them off; the wider
20	        /// region's numbers follow from it.
21	        /// </summary>
22	        public double DensityPerKm2;
23	        /// <summary>Yearly growth rate when far below capacity.</summary>
24	        public double BirthRate;
25	        /// <summary>Share of the regional population that spends the warm season in the valley, if nothing scares them off.</summary>
26	        public double ValleyShare;
27	        /// <summary>Share of the valley's animals that leave for the winter and rejoin the region.</summary>
28	        public double MigratoryFraction;
29	
30	        // ---- Body and behavior ----
31	        /// <summary>How much damage it takes to kill, in units of one good spear hit.</summary>
32	        public double Size;
33	        /// <summary>How early it notices danger. Flight distance ≈ wariness × 60 m, more when afraid.</summary>
34	        public double Wariness;
35	        /// <summary>How likely it turns and fights when wounded or cornered.</summary>
36	        public double Aggression;
37	        /// <summary>How hard it is to run down.</summary>
38	        public double Speed;
39	
40	        public bool Predator;
41	        public bool Huntable;
42	        public double Meat;
43	        public int Hides, Sinew, Bone;
44	
45	        public Terrain SummerTerrain, WinterTerrain;
