            for (int y = 0; y < size; y++)
            {
                double riverX = size / 2.0 + size * 0.12 * Math.Sin(y / (size / 7.0) + phase)
                    + (Fractal(seed, 0.5, y * 0.05) - 0.5) * 6;
                for (int x = 0; x < size; x++)
