// ---- Daily ---------------------------------------------------------------------------

internal void Daily()
{
    if (Extinct) return;
    var season = Clock.Season;
    double temp = World.Climate.TemperatureC(season);

    if (Clock.DayOfSeason == 0 && Environment.GetEnvironmentVariable("ANTHRO_DEBUG_SEASONS") != null && Band.Members.Count > 0)
        Console.Error.WriteLine($"SEASON Y{Clock.Year} {Clock.Season,-6} pop {Band.Members.Count,3} | meat {Band.MeatTotal,5:F0} plants {Band.Households.Sum(h => h.Food.Plants),5:F0} stored {Band.Households.Sum(h => h.Food.Stored),5:F0} | avg reserve {Band.Members.Average(m => m.Reserve):F1} | lean-season belief {Band.Members.Average(m => m.Expect.Get("lean:season", 0.2)):F2} | plant stock near camp {ForagePatches.Sum(c => c.PlantStock):F0}");
    if (Clock.DayOfSeason == 0)
    {
        _wolvesSeenThisSeason = false;
        _hungerReportedThisSeason = false;
        if (season == Season.Winter && World.Climate.WinterSeverity > 1)
            Chronicle.Write(Clock, Importance.Notable, "A hard winter set in.");
    }

    double before = Band.FoodTotal;
    foreach (var h in Band.Households)
    {
    foreach (var g in Ecology.Groups)
    {
        if (g.Gone || WorldMap.Distance(g.X, g.Y, Band.CampX, Band.CampY) > WorldMap.FromMeters(5000)) continue;
        _here.Add(g.Species.Predator ? "wolves" : "game");
    }
    if (Clock.Season == Season.Winter && World.Climate.TemperatureC(Season.Winter) < 0) _here.Add("snow");
}

bool AtHand(string material, Person p) => material switch
/// of it and how far they'd have to walk on tired legs. In rations.
/// </summary>
double Value(Simulation sim, Person m, AnimalGroup g, int partySize, double hope)
{
    var sp = g.Species;
    double horizon = sim.World.Climate.TemperatureC(sim.Clock.Season) < 0 ? 20 : 4;
    double canEat = sim.Band.Members.Count * 0.9 * horizon;
    int people = Math.Max(1, sim.Band.Members.Count);
    double hunger = Inheritance.Clamp01(1 - sim.Band.FoodTotal / (people * 0.9) / 6);
void Chase(Simulation sim, List<Person> alive)
{
    if (--_left > 0) return;
    if (Target == null || Target.Gone) { GoBack(); return; }
    double runners = alive.Average(m => (m.B(BodyTrait.Endurance) + m.M(MindTrait.Boldness)) / 2 * (1 - m.Fatigue * 0.5));
    double caught = runners * (1 - Target.Species.Speed) + 0.4 * Math.Min(1, _damage / Target.Species.Size);
    // Deep snow: animals flounder but so do hunters, unless they have snowshoes, which turns the snow to their advantage.
    if (sim.Clock.Season == Core.Season.Winter && sim.World.Climate.TemperatureC(Core.Season.Winter) < 0)
        caught *= alive.All(m => m.Knows.Contains("hide.snowshoe")) ? 1.4 : 0.7;
    if (sim.Rng.Chance(caught)) { Current = Phase.Strike; return; }
    _damage = 0;
    GoBack();

