        public void DailySpoil(double temperatureC, int storageLevel, bool coldCaches, double care = 1)
        {
            Meat *= temperatureC < 0 ? (coldCaches ? 0.995 : 0.97) : 0.8;
            MeatAge = Meat < 0.5 ? 0 : MeatAge + (temperatureC < 0 ? 0.2 : 1);
            Plants *= 0.92;
            Cooked *= 0.85;
            Stored *= 1 - (0.004 - storageLevel * 0.001) * care;
            Dried *= 1 - (0.003 - storageLevel * 0.0007) * care;
        }
            child.AddAffinity(carer, 0.2);
            Chronicle.Write(Clock, Importance.Detail, $"{carer.Name} took in {child.Name}.");
        }

        static void MoveFood(FoodStore from, FoodStore to)
        {
            to.AddMeat(from.Meat);
            to.Plants += from.Plants;
            to.Stored += from.Stored;
            to.Cooked += from.Cooked;
            to.Dried += from.Dried;
            from.Meat = from.Plants = from.Stored = from.Cooked = from.Dried = 0;
        }

