        double surplus = Math.Max(0, home.Food.Perishable - mouths * 2);
        if (surplus > 2)
            options.Add(new Option(Verb.Preserve, Inheritance.Clamp01(surplus / (mouths * 2)) * (0.6 + Foresight(sim, p) * 1.5 + p.I(Interest.Hearth) * 0.3),
