    if (age < 16 || age > 45) return;
    // Fertility peaks in the mid-twenties and falls off toward the mid-forties.
    // Fertility is low in the late teens (forager women first give birth around 19), peaks in the
    // twenties, and falls off toward the mid-forties.
    double byAge = age < 22 ? 0.2 + 0.8 * (age - 16) / 6 : age < 30 ? 1 : Math.Max(0, 1 - (age - 30) / 15);
    double condition = Physiology.Fecundity(p, age);
    var youngest = p.Children.Where(c => c.Alive).Select(c => c.AgeYears(Clock)).DefaultIfEmpty(99).Min();
    // On-demand nursing for years keeps ovulation suppressed (forager births come ~4 years apart).
    double nursing = youngest < 4 ? Math.Pow(youngest / 4, 2) : 1;
    if (Rng.Chance(0.12 / 30 * byAge * condition * nursing * p.Health)) { p.DueDay = Clock.Day + 270; p.ExpectingWith = p.Partner; }
}

void GiveBirth(Person mother)
{
    mother.DueDay = -1;
    var father = mother.ExpectingWith ?? mother.Partner!;
    mother.ExpectingWith = null;
    var child = NewChild(mother, father, 0);
    child.Health = 0.6 + 0.4 * mother.Satiety;
    ThisYear.Births++;
    Chronicle.Write(Clock, Importance.Detail, $"{child.Name} was born to {mother.Name} and {father.Name}.");

    // Births go wrong more often for older, weaker or hungrier mothers.
    double age = mother.AgeYears(Clock);
    double complication = 0.01 + Math.Max(0, age - 35) * 0.004 + (1 - mother.Health) * 0.05 + (1 - mother.Satiety) * 0.03;
    if (Rng.Chance(complication))
    {
        // Bleeding and infection after birth: about half of serious complications kill, which
        // comes to roughly one death per hundred births, as among real foragers.
        mother.Health -= Rng.Range(0.5, 1.5);
        if (mother.Health <= 0) Kill(mother, "childbirth");
        else Chronicle.Write(Clock, Importance.Notable, $"{mother.Name} barely survived giving birth to {child.Name}.");
    }
}

