patch('Activities/Decider.cs',[
("""        /// <summary>
        /// How strongly someone feels the need to put food by for winter: how lean they remember
        /// winters being, how patient they are, and how far short of enough the camp's keeping-food is.
        /// Only felt as winter approaches.
        /// </summary>
        public static double Foresight(Simulation sim, Person p)
        {
            var season = sim.Clock.Season;
            if (season != Season.Autumn && !(season == Season.Summer && sim.Clock.DayOfSeason > 45)) return 0;
            double lean = p.Expect.Get("lean:season", 0.2);
            var home = sim.HomeOf(p);
            // Enough keeping-food in their own hearth to carry them through as much of the lean months
            // (winter and spring, until the land greens) as they expect to go hungry.
            double enough = home.Members.Count * 0.9 * SimClock.DaysPerSeason * 2 * lean;
            // Keeping-food is anything that lasts: nuts and grain, and whatever has been dried.
            double shortfall = enough <= 0 ? 0 : Inheritance.Clamp01(1 - (home.Food.Stored + home.Food.Dried) / enough);
            return lean * (0.5 + p.M(MindTrait.Patience) * 0.5) * shortfall;
        }""",
"""        /// <summary>
        /// How strongly someone feels the need to put food by: how lean they've learned the coming two
        /// seasons get (the nearer one counting more), how patient they are, and how far short of
        /// enough their hearth's keeping-food is. No calendar: it rises as seasons they know to be lean
        /// draw near, so a band that has never gone hungry doesn't bother, and one that has learned
        /// its springs are hard starts storing in the autumn.
        /// </summary>
        public static double Foresight(Simulation sim, Person p)
        {
            int s = (int)sim.Clock.Season;
            double next = p.Expect.Get(Simulation.LeanTopic((Season)((s + 1) % 4)), 0.2);
            double after = p.Expect.Get(Simulation.LeanTopic((Season)((s + 2) % 4)), 0.2);
            double ahead = next * 0.6 + after * 0.4;
            return ahead * (0.5 + p.M(MindTrait.Patience) * 0.5) * StoreShortfall(sim, p, next, after);
        }

        /// <summary>
        /// How far short (0-1) the hearth's keeping-food (nuts, grain, dried food) is of carrying it through
        /// as much of the coming two seasons as they expect to go hungry.
        /// </summary>
        static double StoreShortfall(Simulation sim, Person p, double next, double after)
        {
