1	using System;
2	using System.Collections.Generic;
3	using System.Linq;
4	using Anthro.Sim.Core;
5	using Anthro.Sim.People;
6	using Anthro.Sim.World;
7	
8	namespace Anthro.Sim.Activities
9	{
10	    public readonly struct Option
11	    {
12	        public readonly Verb Verb;
13	        public readonly double Score;
14	        public readonly Func<Activity> Make;
15	
16	        public Option(Verb verb, double score, Func<Activity> make) { Verb = verb; Score = score; Make = make; }
17	    }
18	
19	    /// <summary>
20	    /// What a person could do right now, and how much each pulls on them:
21	    ///   need it meets × expected result + interest + trait pulls + social pull.
22	    /// The same scores answer "what would I rather be doing?" when someone asks them to join a hunt.
23	    /// </summary>
24	    public static class Decider
25	    {
26	        public static Activity Choose(Simulation sim, Person p)
27	        {
28	            var clock = sim.Clock;
29	            if (clock.IsNight)
30	            {
31	                int hour = clock.Hour;
32	                return new Sleep(p, Math.Max(1, hour >= clock.Sunrise ? 24 - hour + clock.Sunrise : clock.Sunrise - hour));
33	            }
34	            double age = p.AgeYears(clock);
35	            if (age < 3)
36	                return age >= 1 && p.Stomach < 0.4 && sim.Band.FoodTotal > 0 ? new Eat(p) : (Activity)new Play(p);
37	
38	            // Noise before taking the max: a softmax in disguise, so people aren't perfectly predictable.
39	            Func<Activity>? best = null;
40	            double bestScore = double.NegativeInfinity;
41	            foreach (var o in Options(sim, p))
42	            {
43	                double score = o.Score + sim.Rng.Normal(0, 0.15);
44	                if (score > bestScore) { bestScore = score; best = o.Make; }
45	            }
46	            return best!();
47	        }
48	
49	        /// <summary>The strongest pull other than <paramref name="except"/>: what this person gives up to do it.</summary>
50	        public static double BestAlternative(Simulation sim, Person p, Verb except)
51	        {
52	            var others = Options(sim, p).Where(o => o.Verb != except).ToList();
53	            return others.Count == 0 ? 0 : others.Max(o => o.Score);
54	        }
55	
56	        public static double ScoreOf(Simulation sim, Person p, Verb verb)
57	        {
58	            foreach (var o in Options(sim, p)) if (o.Verb == verb) return o.Score;
59	            return double.NegativeInfinity;
60	        }
61	
62	        /// <summary>
63	        /// How strongly someone feels the need to put food by: how lean they have learned the coming two
64	        /// seasons get (the nearer one counting more), how patient they are, and how far short of
65	        /// enough their hearth's keeping-food is. No calendar: it rises as seasons they know to be lean
66	        /// draw near, so a band that has never gone hungry doesn't bother, and one that has learned
67	        /// its springs are hard starts storing in the autumn.
68	        /// </summary>
69	        public static double Foresight(Simulation sim, Person p)
70	        {
71	            var (next, after) = LeanAhead(sim, p);
72	            double ahead = next * 0.6 + after * 0.4;
73	            var home = sim.HomeOf(p);
74	            double enough = home.Members.Count * 0.9 * SimClock.DaysPerSeason * (next + after);
75	            double shortfall = enough <= 0 ? 0 : Inheritance.Clamp01(1 - (home.Food.Stored + home.Food.Dried) / enough);
76	            return ahead * (0.5 + p.M(MindTrait.Patience) * 0.5) * shortfall;
77	        }
78	
79	        /// <summary>How lean this person expects the next season and the one after to be.</summary>
80	        static (double next, double after) LeanAhead(Simulation sim, Person p)
81	        {
82	            int s = (int)sim.Clock.Season;
83	            return (p.Expect.Get(Simulation.LeanTopic((Season)((s + 1) % 4)), 0.2),
84	                    p.Expect.Get(Simulation.LeanTopic((Season)((s + 2) % 4)), 0.2));
85	        }
86	
87	        /// <summary>The rations of keeping-food someone's hearth is short for the lean seasons they expect.</summary>
88	        public static double StoreShortfallRations(Simulation sim, Person p)
89	        {
90	            var (next, after) = LeanAhead(sim, p);
91	            var home = sim.HomeOf(p);
92	            return Math.Max(0, home.Members.Count * 0.9 * SimClock.DaysPerSeason * (next + after) - home.Food.Stored - home.Food.Dried);
93	        }
94	
95	        static double MaxGrievance(Person p)
96	        {
97	            double m = 0;
98	            foreach (var v in p.Grievance.Values) if (v > m) m = v;
99	            return m;
100	        }
101	
102	        public static List<Option> Options(Simulation sim, Person p)
103	        {
104	            var clock = sim.Clock;
105	            int hour = clock.Hour;
106	            double age = p.AgeYears(clock);
107	            var band = sim.Band;
108	            int people = Math.Max(1, band.Members.Count);
109	
110	            // Need: mostly how long their own hearth's food would last (with an eye on the camp's),
111	            // and meat on its own (it rots, and people crave it). Hunger is also an empty belly and
112	            // the body thinning.
113	            var home = sim.HomeOf(p);
114	            double foodDays = home.DaysOfFood * 0.7 + band.FoodTotal / (people * 0.9) * 0.3;
115	            double hunger = Math.Max(Inheritance.Clamp01(1 - foodDays / 6),
116	                            Math.Max(1 - p.Satiety, Inheritance.Clamp01((0.5 - p.Stomach) * 2) * 0.6));
117	            // Craving meat: people need some animal food (protein, fat), and miss it when it's been a
118	            // small part of what the family's been living on; past about 40% of the diet more lean meat
119	            // adds little (the protein ceiling), and the craving is gone.
120	            double meatHunger = Inheritance.Clamp01((0.4 - home.Food.AnimalShare) / 0.3);
121	            // More food is only worth what will be eaten before it spoils. With fresh food piled up
122	            // at home (or meat hanging all over camp), going out for more is worth little, and people
123	            // rest, talk and make things instead, as real foragers do in good times.
124	            double freshDays = (home.Food.Meat + home.Food.Plants + home.Food.Cooked) / (home.Members.Count * 0.9);
125	            double room = Inheritance.Clamp01(1 - freshDays / 6);
126	            double meatRoom = Inheritance.Clamp01(1 - band.MeatTotal / (people * 0.9) / sim.MeatKeepsDays);
127	            // Going hunting just to have more is only worth it while the camp couldn't eat everything it
128	            // already has in the time meat keeps (nuts, roots and dried food count too).
129	            double huntRoom = Inheritance.Clamp01(1 - band.FoodTotal / (people * 0.9) / sim.MeatKeepsDays);
130	            // A trip out needs enough light left to get there, work, and get back.
131	            bool daylightAhead = clock.DaylightLeft >= 6;
132	            double maturity = Physiology.Maturity(age);
133	            var options = new List<Option>();
134	
135	            options.Add(new Option(Verb.Rest, p.Fatigue * 1.5 + (1 - p.Health) + p.Injury + p.Sickness * 3 + 0.05, () => new Rest(p)));
136	            // Hunger is the belly and, more slowly, the body's reserves running down.
137	            // Eating is from one's own hearth; with nothing there, the choices are to go and get food or ask for it.
138	            if (home.Food.Total > 0.05) options.Add(new Option(Verb.Eat, (0.6 - p.Stomach) * 4 + (1 - p.Satiety) * 1.5, () => new Eat(p)));
139	            // Hungry people don't sit around talking.
140	            options.Add(new Option(Verb.Socialize, (0.2 + p.M(MindTrait.Sociability) * 0.5 + (clock.DaylightLeft <= 1 ? 0.7 : 0)) * (1 - hunger * 0.7), () => new Socialize(p)));
141	
142	            // Play fades as children grow.
143	            if (maturity < 0.8) options.Add(new Option(Verb.Play, 1.0 - maturity, () => new Play(p)));
144	
145	            // Food work is weighed the way real foragers weigh it: by the food an hour of it has
146	            // actually been bringing in (learned), scaled by need, with interest, nerve and the hope
147	            // of standing as smaller pulls.
148	            const double Reference = 0.4;
149	            if (maturity > 0.2 && daylightAhead)
150	            {
151	                // Nuts and grain keep: the urge to store pulls toward gathering them.
152	                double drive = 0.25 * room + hunger * 1.5 + Foresight(sim, p);
153	                double yield = p.Expect.Get(Verb.Forage, Forage.FallbackPerHour) / Reference;
154	                options.Add(new Option(Verb.Forage, drive * yield * (0.7 + p.I(Interest.Plants) * 0.3 + p.M(MindTrait.Patience) * 0.1),
155	                    () => new Forage(p)));
156	            }
157	
158	            if (maturity > 0.3 && daylightAhead && sim.FishSpots.Count > 0 && FishingMethods.CanFish(p))
159	            {
160	                double drive = 0.25 * room + Math.Max(hunger, meatHunger * 0.5 * meatRoom) * 1.5 + (Preserve.CanPreserve(p) ? Foresight(sim, p) : 0);   // fish keeps only for those who can dry it
161	                double yield = p.Expect.Get(Verb.Fish, Fish.FallbackPerHour) / Reference;
162	                options.Add(new Option(Verb.Fish, drive * yield * (0.7 + p.I(Interest.Water) * 0.3 + p.M(MindTrait.Patience) * 0.1),
163	                    () => new Fish(p)));
164	            }
165	
166	            // Setting and checking traps: where small game has been seen, for those who know how.
167	            if (maturity > 0.4 && clock.DaylightLeft >= 3 && TrappingMethods.Efficiency(p) > 0 && p.Map.Game.Values.Any(s => s.Species.Size < 1 && clock.Day - s.Day < 14))
168	            {
169	                double drive = 0.25 * huntRoom + Math.Max(hunger, meatHunger * 0.7 * meatRoom) * 1.5;
170	                double yield = p.Expect.Get(Verb.Trap, Trap.FallbackPerHour) / Reference;
171	                options.Add(new Option(Verb.Trap, drive * yield * (0.7 + p.I(Interest.Animals) * 0.2 + p.M(MindTrait.Patience) * 0.2), () => new Trap(p)));
172	            }
173	
174	            if (daylightAhead && HuntParty.CanHunt(sim, p))
175	            {
176	                // Meat hanging all over camp (shared out after a big kill) takes away the craving too.
177	                // Meat keeps only for those who can dry it: for them, the urge to store counts here too.
178	                double drive = 0.25 * huntRoom + Math.Max(hunger, meatHunger * 0.7 * meatRoom) * 1.5
179	                               + (Preserve.CanPreserve(p) ? Foresight(sim, p) : 0);
180	                double yield = Math.Max(0, p.Expect.Get(Verb.Hunt, HuntParty.FallbackPerHour)) / Reference;
181	                double standing = p.M(MindTrait.Boldness) * p.Drives[(int)Drive.Standing] * 0.4;
182	                // Late pregnancy and nursing make a long, rough day away from camp costly.
183	                double tied = p.DueDay >= 0 || p.Sex == Sex.Female && p.Children.Any(c => c.Alive && c.AgeYears(clock) < 2) ? 0.6 : 0;
184	                options.Add(new Option(Verb.Hunt, drive * yield * (0.7 + p.I(Interest.Animals) * 0.3 + p.B(BodyTrait.Strength) * 0.1) + standing - tied,
185	                    () => new Hunt(p, new HuntParty(p))));
186	            }
187	
188	            if (Physiology.CraftCapacity(p, age) > 0.6)
189	            {
190	                int adults = Math.Max(1, band.Adults(clock).Count());
191	                double toolNeed = Inheritance.Clamp01(1 - band.Materials.Tools / (adults * 1.5));
192	                if (band.Materials.Flint > 0)
193	                    options.Add(new Option(Verb.Knap, toolNeed * 1.3 + p.I(Interest.StoneEarth) * 0.4 + p.S(Skill.Knapping) * 0.2, () => new Knap(p)));
194	                else if (daylightAhead)
195	                    options.Add(new Option(Verb.GatherFlint, toolNeed * 1.2 + p.I(Interest.StoneEarth) * 0.3, () => new GatherFlint(p)));
196	            }
197	
198	            // The hearth: cooking what's raw, keeping the fire fed, preserving surplus.
199	            if (maturity > 0.5)
200	            {
201	                double mouths = home.Members.Count * 0.9;
202	                double rawToCook = Math.Min(home.Food.Raw, mouths * 1.5) - home.Food.Cooked;
203	                if (rawToCook > 0.5 && home.FireLit)
204	                    options.Add(new Option(Verb.Cook, Inheritance.Clamp01(rawToCook / mouths) * (0.5 + p.I(Interest.Hearth) * 0.5 + p.S(Skill.Cooking) * 0.2) * (0.5 + hunger),
205	                        () => new Cook(p)));
206	
207	                double fuelDays = home.Fuel / Cuisine.DailyBurn(clock.Season);
208	                if (clock.DaylightLeft >= 5)
209	                    options.Add(new Option(Verb.GatherWood, Inheritance.Clamp01(1 - fuelDays / 4) * 1.4 * (0.7 + p.I(Interest.Hearth) * 0.3 + p.B(BodyTrait.Endurance) * 0.2),
210	                        () => new GatherWood(p)));
211	
212	                if (Preserve.CanPreserve(p))
213	                {
214	                    // Fresh food beyond what the hearth will eat in a couple of days will rot unless it's dried.
215	                    double surplus = Math.Max(0, home.Food.Perishable - mouths * 2);
216	                    if (surplus > 2)
217	                        options.Add(new Option(Verb.Preserve, Inheritance.Clamp01(surplus / (mouths * 2)) * (0.6 + Foresight(sim, p) * 1.5 + p.I(Interest.Hearth) * 0.3),
218	                            () => new Preserve(p)));
219	                }
220	            }
221	
222	            // When the hearth is running short: ask another hearth, or take from one. Each is weighed by
223	            // what this person has come to expect it brings (their own experience, what they've seen and
224	            // been told, the culture they grew up in), by guilt toward the people it would hurt, and,
225	            // for taking, by how likely they are to be seen.
226	            if (maturity > 0.6 && hunger > 0.3 && home.DaysOfFood < 2)
227	            {
228	                double amount = home.Members.Count * 0.9;
229	                int watchers = Math.Max(0, sim.AwakeInCampCount - 1);
230	                double pSeen = 1 - Math.Pow(0.85, watchers);
231	                Household? askAt = null, takeAt = null;
232	                double bestAsk = 0, bestTake = 0;
233	                foreach (var h in band.Households)
234	                {
235	                    if (h == home || h.Food.Total < 1) continue;
236	                    var rel = sim.RelationTo(p, h);
237	                    var owner = h.Adults(clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
238	                    double guilt = owner == null ? 0 : Simulation.Guilt(p, owner);
239	                    double plenty = Math.Min(1, Simulation.SpareFor(h, home) / amount);
240	                    double ask = Simulation.Expects(p, Act.Ask, rel) * plenty;
241	                    double take = pSeen * Simulation.Expects(p, Act.Take, rel, true) + (1 - pSeen) * Simulation.Expects(p, Act.Take, rel, false) - guilt;
242	                    if (ask > bestAsk) { bestAsk = ask; askAt = h; }
243	                    if (take > bestTake) { bestTake = take; takeAt = h; }
244	                }
245	                double drive = 0.25 + hunger * 1.5;
246	                // Taking is only worth something to people who are actually going short: how thin
247	                // anyone at their hearth is getting, not just how low the store is.
248	                double thinning = home.Members.Select(m => 1 - m.Satiety).DefaultIfEmpty(0).Max();
249	                bestTake *= Math.Min(1, thinning * 2);
250	                // An hour spent asking can bring in a day's food: weighed like any other hour of getting food.
251	                if (askAt != null) { var at = askAt; options.Add(new Option(Verb.Ask, drive * bestAsk / Reference, () => new AskFor(p, at, amount))); }
252	                if (takeAt != null) { var at = takeAt; options.Add(new Option(Verb.Take, drive * bestTake / Reference * 0.5 * (1.3 - p.M(MindTrait.Warmth) * 0.6), () => new TakeFrom(p, at, amount))); }
253	            }
254	
255	            // Anger at someone in camp: face them over it, or go for them. Anger is innate; what
256	            // confronting or hitting brings is learned.
257	            if (maturity > 0.7 && MaxGrievance(p) > 0.5)
258	            {
259	                Person? target = null;
260	                double anger = 0;
261	                foreach (var o in band.Members)
262	                {
263	                    double g = p.GetGrievance(o);
264	                    if (g > anger && o != p && Simulation.AwakeInCamp(o)) { anger = g; target = o; }
265	                }
266	                if (target != null && anger > 0.5)
267	                {
268	                    var rel = sim.RelationTo(p, target);
269	                    double heat = anger / (anger + 3);
270	                    double guilt = Simulation.Felt(Simulation.Guilt(p, target)) * 0.5;
271	                    double confront = sim.ConfrontValue(p, target);
272	                    // Fear of them, and of the kin and friends who'd stand with them.
273	                    double fear = sim.Backing(target, p) / Math.Max(0.1, p.B(BodyTrait.Strength) * p.Health) * 0.3 + p.Injury;
274	                    double attack = heat * p.M(MindTrait.Temper) * 1.5 + Simulation.Felt(Simulation.Expects(p, Act.Attack, rel)) - guilt - fear * p.W(Drive.Safety);
275	                    var t = target;
276	                    if (confront > 0) options.Add(new Option(Verb.Confront, confront, () => new Confront(p, t)));
277	                    if (attack > 0) options.Add(new Option(Verb.Attack, attack, () => new Assault(p, t)));
278	                }
279	            }
280	
281	            // Calling others to take a hearth's food by force: when angry at a household, or hungry
282	            // while it sits on plenty, and enough people are about to come along.
283	            if (maturity > 0.8 && (MaxGrievance(p) > 1.5 || hunger > 0.6))
284	            {
285	                int about = sim.AwakeInCampCount;
286	                if (about >= 2)
287	                {
288	                    Household? target = null;
289	                    double best = 0;
290	                    foreach (var h in band.Households)
291	                    {
292	                        if (h == home || Simulation.Spare(h) < 1) continue;
293	                        double v = sim.RallyValue(p, h);
294	                        if (v > best) { best = v; target = h; }
295	                    }
296	                    if (target != null) { var t = target; options.Add(new Option(Verb.Rally, best, () => new Rally(p, t))); }
297	                }
298	            }
299	
300	            // Raiding another band: anger at that band (from harms done by any of its people, and what
301	            // others have told), set against fear, a culture of peace, and what fighting has brought.
302	            if (maturity > 0.8 && p.BandGrievance.Count > 0 && p.Health > 0.6)
303	            {
304	                Simulation? foe = null;
305	                double anger = 0;
306	                foreach (var b in sim.Region.Bands)
307	                {
308	                    if (b == sim || b.Extinct) continue;
309	                    double g = p.GetBandGrievance(b.Id);
310	                    // Only a band whose camp they know of.
311	                    if (g > anger && p.Map.Camps.TryGetValue(b.Id, out var where) && clock.Day - where.day < 60
312	                        && WorldMap.Distance(where.x, where.y, band.CampX, band.CampY) < Region.KnownRange) { anger = g; foe = b; }
313	                }
314	                if (foe != null && anger > 1)
315	                {
316	                    double v = sim.RaidValue(p, foe);
317	                    var f = foe;
318	                    if (v > 0) options.Add(new Option(Verb.Raid, v, () => new Raid(p, f)));
319	                }
320	            }
321	
322	            // Going to visit another band: missing people there, or hoping to find a partner.
323	            if (daylightAhead && sim.VisitPulls.TryGetValue(p, out var visit))
324	                options.Add(new Option(Verb.Visit, visit.pull, () => new Visit(p, visit.band)));
325	
326	            var child = p.Children.Where(c => c.Alive && c.AgeYears(clock) < 4).OrderBy(c => c.AgeYears(clock)).FirstOrDefault();
327	            if (child != null && child.CareToday < 6)
328	                options.Add(new Option(Verb.Care, 0.5 + p.M(MindTrait.Warmth) * 0.6 + (6 - child.CareToday) / 6 * 0.6, () => new Care(p, child)));
329	
330	            if (maturity > 0.6 && p.Sickness < 0.2)
331	            {
332	                Person? sick = null;
333	                double worst = 0;
334	                foreach (var o in sim.SickThisHour)
335	                {
336	                    if (o == p || o.CareToday >= 4) continue;
337	                    double v = p.GetAffinity(o) + o.Sickness;
338	                    if (sick == null || v > worst) { worst = v; sick = o; }
339	                }
340	                if (sick != null && (child == null || child.CareToday >= 6))
341	                    options.Add(new Option(Verb.Care, p.M(MindTrait.Warmth) * 0.8 + p.S(Skill.Caring) * 0.3 + p.I(Interest.Healing) * 0.5 + p.GetAffinity(sick) * 0.6 + sick.Sickness * 0.5,
342	                        () => new Care(p, sick)));
343	            }
344	
345	            if (maturity > 0.25 && maturity < 1)
346	            {
347	                Person? teacher = null;
348	                double fondest = -1;
349	                foreach (var o in sim.WorkingThisHour)
350	                {
351	                    if (o == p || !(o.Current is Knap || o.Current is Care || o.Current is Cook || o.Current is Preserve)) continue;
352	                    double v = p.GetAffinity(o);
353	                    if (v > fondest) { fondest = v; teacher = o; }
354	                }
355	                if (teacher != null)
356	                {
357	                    var (skill, interest) = teacher.Current is Knap ? (Skill.Knapping, Interest.StoneEarth)
358	                        : teacher.Current is Care ? (Skill.Caring, Interest.People) : (Skill.Cooking, Interest.Hearth);
359	                    options.Add(new Option(Verb.WatchAndLearn, 0.5 + p.M(MindTrait.Curiosity) * 0.6, () => new WatchAndLearn(p, teacher, skill, interest)));
360	                }
361	            }
362	            // What this person cares about weighs their options: their own drive weights.
363	            for (int i = 0; i < options.Count; i++)
364	            {
365	                var o = options[i];
366	                double w = o.Verb switch
367	                {
368	                    Verb.Forage or Verb.Fish or Verb.Trap or Verb.Ask or Verb.Take or Verb.Eat or Verb.Preserve => p.W(Drive.Food),
369	                    Verb.Hunt => p.W(Drive.Food) * 0.6 + p.W(Drive.Standing) * 0.4,
370	                    Verb.Rest or Verb.GatherWood or Verb.Cook => p.W(Drive.Comfort),
371	                    Verb.Socialize or Verb.Visit or Verb.Play => p.W(Drive.Company),
372	                    Verb.Care => p.W(Drive.Family),
373	                    Verb.Confront or Verb.Attack or Verb.Rally or Verb.Raid => p.W(Drive.Standing) / p.W(Drive.Safety),
374	                    _ => 1,
375	                };
376	                if (w != 1) options[i] = new Option(o.Verb, o.Score * w, o.Make);
377	            }
378	
379	            // When people are hungry, everything that doesn't get food or keep them alive fades.
380	            for (int i = 0; i < options.Count; i++)
381	            {
382	                var o = options[i];
383	                bool essential = o.Verb == Verb.Forage || o.Verb == Verb.Hunt || o.Verb == Verb.Fish || o.Verb == Verb.Trap || o.Verb == Verb.Eat || o.Verb == Verb.Rest
384	                                 || o.Verb == Verb.Care || o.Verb == Verb.Sleep || o.Verb == Verb.Socialize
385	                                 || o.Verb == Verb.Cook || o.Verb == Verb.GatherWood || o.Verb == Verb.Preserve
386	                                 || o.Verb == Verb.Ask || o.Verb == Verb.Take;
387	                if (!essential) options[i] = new Option(o.Verb, o.Score * (1 - hunger * 0.7), o.Make);
388	            }
389	            return options;
390	        }
391	    }
392	}
