import os
os.chdir(r'C:/Users/nars7/Downloads/Ideas and Thoughts/Anthro/Anthro.Sim')

def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:100])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

patch('Ecology/AnimalGroup.cs', [
("using System.Collections.Generic;\n", "using System.Collections.Generic;\nusing Anthro.Sim.Core;\n"),
("""        /// <summary>Where the group has been each day this past week: the trail it leaves on the land.</summary>""",
"""        /// <summary>This group's own chance stream, so groups can be updated in parallel and still replay exactly.</summary>
        public Rng? Rng;

        /// <summary>Where the group has been each day this past week: the trail it leaves on the land.</summary>"""),
])

s = open('Ecology/EcologySystem.cs', encoding='utf-8').read()
# Give every new group its own chance stream (groups are only ever created one at a time).
s = s.replace("var g = new AnimalGroup(_nextId++, sp, size, c.X, c.Y) { Migratory = sim.Rng.Chance(sp.MigratoryFraction) };",
              "var g = new AnimalGroup(_nextId++, sp, size, c.X, c.Y) { Migratory = sim.Rng.Chance(sp.MigratoryFraction) };\n                    g.Rng = sim.Rng.Fork((ulong)g.Id);", 1)
s = s.replace("_groups.Add(new AnimalGroup(_nextId++, sp, 2, c.X, c.Y) { Condition = g.Condition });",
              "_groups.Add(new AnimalGroup(_nextId++, sp, 2, c.X, c.Y) { Condition = g.Condition, Rng = sim.Rng.Fork((ulong)_nextId) });", 1)
s = s.replace("var split = new AnimalGroup(_nextId++, sp, part, g.X, g.Y) { Migratory = g.Migratory, Condition = g.Condition, Away = g.Away, LeftDay = g.LeftDay, Shy = g.Shy };",
              "var split = new AnimalGroup(_nextId++, sp, part, g.X, g.Y) { Migratory = g.Migratory, Condition = g.Condition, Away = g.Away, LeftDay = g.LeftDay, Shy = g.Shy, Rng = sim.Rng.Fork((ulong)_nextId) };", 1)

old_start = s.index("            using (Profiler.Measure(\"eco groups\"))\n            foreach (var g in _groups)")
old_end = s.index("            using (Profiler.Measure(\"eco packs\"))")
new = '''            // Grazers and browsers each look after themselves, so they're updated side by side on all the
            // processor's cores; each draws on its own chance stream, so the result is the same every run.
            var grazers = _groups.Where(g => !g.Gone && !g.Species.Predator).ToList();
            var leaving = new System.Collections.Concurrent.ConcurrentBag<AnimalGroup>();
            using (Profiler.Measure("eco groups"))
                System.Threading.Tasks.Parallel.ForEach(grazers, g => { if (Graze(sim, g, season, climate, world)) leaving.Add(g); });
            foreach (var g in leaving.OrderBy(g => g.Id)) Leave(sim, g);
            // Wolves follow the herds as they now stand.
            foreach (var g in _groups)
            {
                if (g.Gone || !g.Species.Predator) continue;
                g.Fear = Math.Max(0, g.Fear - 0.04);
                g.Condition = Math.Max(0, Math.Min(1, 1.2 - g.Hunger));
                using (Profiler.Measure("eco follow")) FollowPrey(sim, g);
                AgeAndMove(sim, g, sim.Rng);
            }

'''
s = s[:old_start] + new + s[old_end:]

# The per-group day, factored out; returns true when the herd has reached the edge and leaves.
s = s.replace('''        // ---- Coming and going --------------------------------------------------------------------''',
'''        /// <summary>A grazing group's day: feeding, condition, choosing ground, deaths, moving. True if it leaves the map today.</summary>
        bool Graze(Region sim, AnimalGroup g, Season season, Climate climate, WorldMap world)
        {
            var sp = g.Species;
            var rng = g.Rng ?? sim.Rng;
            double toCamp = NearestCamp(sim, g.X, g.Y);
            g.Fear = Math.Max(0, g.Fear - 0.04);
            g.Shy *= 0.997;
            if (toCamp < WorldMap.FromMeters(1500)) g.Fear = Math.Min(1, g.Fear + 0.03);
            var here = world[(int)g.X, (int)g.Y];
            double food = Forage(sp, here, climate, season);
            g.Condition = Math.Max(0, Math.Min(1, g.Condition + ConditionRate * (food - Need)));
            bool leaves = false;
            if (g.Leaving) leaves = AtEdge(g);
            else if (WorldMap.Distance(g.X, g.Y, g.TargetX, g.TargetY) < WorldMap.FromMeters(300) || food < Need
                     || rng.Chance(0.05) || (g.Fear > 0.3 && toCamp < WorldMap.FromMeters(3000)))
                ChooseRange(sim, g, season, rng);
            // Hunger and cold kill the thinnest first.
            if (g.Condition < Starving)
            {
                int died = Math.Min(g.Count, rng.Poisson(g.Count * (Starving - g.Condition) * 0.05));
                g.Count -= died; Count(sp, "starved", died);
            }
            if (!leaves) AgeAndMove(sim, g, rng);
            return leaves;
        }

        /// <summary>Deaths of age, disease and accident (less what wolves already culled), then the day's walk, leaving a trail.</summary>
        void AgeAndMove(Region sim, AnimalGroup g, Rng rng)
        {
            var sp = g.Species;
            int old = Math.Min(g.Count, rng.Poisson(g.Count * sp.DeathRate / SimClock.DaysPerYear));
            int spared = Math.Min(old, g.Culled);
            g.Culled -= spared; old -= spared;
            g.Count -= old; Count(sp, "old", old);
            if (g.Away) return;
            g.Trail.Add((g.X, g.Y, sim.Clock.Day));
            if (g.Trail.Count > 8) g.Trail.RemoveAt(0);
            Step(g, WorldMap.FromMeters(sp.Predator ? 6000 : 3000));
        }

        // ---- Coming and going --------------------------------------------------------------------''', 1)

# ChooseRange draws from the group's own stream.
s = s.replace("        void ChooseRange(Region sim, AnimalGroup g, Season season)\n        {",
              "        void ChooseRange(Region sim, AnimalGroup g, Season season, Rng rng)\n        {", 1)
s = s.replace("                var c = NearbyCell(sim.World, sim.Rng, g.X, g.Y, reach);", "                var c = NearbyCell(sim.World, rng, g.X, g.Y, reach);", 1)
open('Ecology/EcologySystem.cs', 'w', encoding='utf-8').write(s)
print('ok')

