                                                 && !(c.Mother != mover && c.Mother != null && from.Band.Members.Contains(c.Mother))
                                                 && !(c.Father != mover && c.Father != null && from.Band.Members.Contains(c.Father))).ToList();
            Region.Move(new List<Person> { mover }.Concat(kids).ToList(), from, to, partner);
            from.Chronicle.Write(Clock, Importance.Notable, $"{mover.Name} paired with {partner.Name} and left to live with the {to.Band.Name} band.");
            to.Chronicle.Write(Clock, Importance.Notable, $"{mover.Name} of the {from.Band.Name} band paired with {partner.Name} and joined the band.");
        }
        // ---- Visiting ------------------------------------------------------------------------

        /// <summary>
        /// How much each adult wants to go and visit another band, and which one: missing kin and
        /// friends who live there, and, for the unpaired with no one suitable at home, the hope of
        /// finding a partner. Longing grows with the time since they last went. People know roughly
        /// where the bands within a few days' walk are camped.
        /// </summary>
        void UpdateVisitPulls()
        {
            VisitPulls.Clear();
            var others = Region.Bands.Where(b => b != this && b.Band.Members.Count > 0 && !Region.Together(this, b)).ToList();
            if (others.Count == 0) return;
            foreach (var p in Band.Members)
            {
                if (p.Map.Camps.Count == 0) continue;
                double age = p.AgeYears(Clock);
                if (age < 16 || p.DueDay >= 0 || p.Sickness > 0.2 || p.Current is Visit) continue;
                if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 4)) continue;
                double longing = Math.Min(1, (Clock.Day - p.LastVisitDay) / 90.0);
                if (longing <= 0) continue;
                bool seeking = p.Partner == null && age <= (p.Sex == Sex.Female ? 40 : 50) && !Band.Members.Any(o => CouldPair(p, o));
                Simulation? best = null;
                double bestPull = 0;
                foreach (var b in others)
                {
                    // Only bands they know where to find (as far as they know).
                    if (!p.Map.Camps.TryGetValue(b.Id, out var where) || Clock.Day - where.day > SimClock.DaysPerYear
                        || WorldMap.Distance(where.x, where.y, Band.CampX, Band.CampY) > Region.KnownRange * (p.Knows.Contains("wayfind.stars") ? 1.5 : 1)) continue;
                    double missing = Ties(p, b.Band.Members) * 0.15;
                    double courting = seeking && b.Band.Members.Any(o => CouldPair(p, o)) ? 0.4 + 0.4 * p.M(MindTrait.Boldness) : 0;
                    double walk = TravelHours(WorldMap.Distance(b.Band.CampX, b.Band.CampY, Band.CampX, Band.CampY), p) * 0.03;
                    double pull = (missing + courting) * longing * (0.5 + p.M(MindTrait.Sociability) * 0.5) - walk;
                    if (pull > bestPull) { bestPull = pull; best = b; }
                }
                if (best != null) VisitPulls[p] = (best, bestPull);
            }
        }

        /// <summary>Bookkeeping check for tests: households list exactly the band's members whose home they are.</summary>
        internal void CheckHouseholds()
        {
            var inHousehold = new HashSet<Person>();
            foreach (var h in Band.Households)
                foreach (var m in h.Members)
                {
                    if (!inHousehold.Add(m)) throw new InvalidOperationException($"{m.Name} is in two households of the {Band.Name} band");
                    if (!Band.Members.Contains(m) || m.Home != h)
                        throw new InvalidOperationException($"{m.Name}#{m.Id} is listed in a {Band.Name} household but inBand={Band.Members.Contains(m)} homeMatches={m.Home == h}");
                }
            foreach (var m in Band.Members)
                if (m.Home != null && !m.Home.Members.Contains(m)) throw new InvalidOperationException($"{m.Name}'s home doesn't list them");
        }

        /// <summary>
        /// Once people know how, they tend the wild grain around a camp they stay at: clearing it,
        /// later scattering seed, later keeping the best seed. Stands within a couple of km grow
        /// richer each week the band stays a month or more; abandoned ones drift back to wild.
        /// </summary>
        void TendGrain()
        {
using System;
using System.Collections.Generic;
using System.Linq;
using Anthro.Sim.Activities;
using Anthro.Sim.Core;
using Anthro.Sim.People;

namespace Anthro.Sim
{
    /// <summary>
    /// Couples and leaders, from people. Jealousy is innate; whether a couple stays together, and
    /// whom people follow, comes from what each person feels and has learned.
    /// </summary>
    public sealed partial class Simulation
    {
        // ---- Jealousy and separation ----------------------------------------------------------------

        /// <summary>
        /// Someone with a partner warms to another person. If the partner is about and notices, they
        /// feel it: anger at the rival, and a little hurt toward their partner. Innate (mate guarding);
        /// what they do about it is their own choice, through the same confronting and fighting as anything else.
        /// </summary>
        public void Jealousy(Person p, Person other)
        {
            var partner = p.Partner;
            if (partner == null || partner == other || other.Sex == p.Sex || p.IsKin(other) || !partner.Alive) return;
            if (p.GetAffinity(other) < 0.3 || !AwakeInCamp(partner) || !Rng.Chance(0.15)) return;
            double sting = (p.GetAffinity(other) - 0.3) * (0.5 + partner.M(MindTrait.Temper)) * 2;
            partner.AddGrievance(other, sting);
            partner.AddAffinity(p, -0.01 * sting);
        }


        /// <summary>
        /// Every so often (each season) people take stock of their marriage, as forager couples do: a
        /// partner who brings home much less than others of their sex, or years together with no
        /// children, wear on a bond (the commonest reasons forager marriages end, along with conflict,
        /// which is already in the bond itself). Whether it ends is weighed against the bond, the
        /// years, and young children at the hearth.
        /// </summary>
        void ReconsiderMarriages()
        {
            var adults = Band.Members.Where(Grown).ToList();
            foreach (var p in adults.ToList())
            {
                var partner = p.Partner;
                if (partner == null || !Band.Members.Contains(partner)) continue;
                var peers = adults.Where(a => a.Sex == partner.Sex && a != partner).ToList();
                double usual = peers.Count == 0 ? partner.Provided : peers.Average(a => a.Provided);
                double provides = usual <= 0 ? 0 : Math.Max(0, Math.Min(1, (usual - partner.Provided) / usual));
                double years = (Clock.Day - p.PairedDay) / (double)SimClock.DaysPerYear;
                var woman = p.Sex == Sex.Female ? p : partner;
                bool childless = years >= 4 && woman.AgeYears(Clock) < 40
                                 && !p.Children.Any(c => c.Alive && (c.Mother == partner || c.Father == partner));
                double strain = provides * 0.8 + (childless ? 0.5 : 0);
                if (strain > 0.1) ConsiderLeaving(p, null, strain);
            }
        }

        /// <summary>How much someone wants another as a partner: fondness and attraction (judged by their own band's tastes).</summary>
        double Desire(Person p, Person o, Simulation judgesBy) =>
            p.GetAffinity(o) + judgesBy.Attraction(o) * 0.2 + Math.Max(0, Following(p, o)) * 0.2 - p.GetGrievance(o) * 0.15
            + (o.Knows.Contains("ochre.body") ? 0.05 : 0);

        /// <summary>
        /// Two unpaired people pair when each is the other's best choice among the free people they
        /// know (within a little), and they know each other well enough to have a bond at all.
        /// </summary>
        public bool WouldPair(Person a, Person b, Simulation aBand, Simulation bBand)
        {
            if (!CouldPair(a, b) || Math.Min(a.GetAffinity(b), b.GetAffinity(a)) < 0.2) return false;
            bool Best(Person p, Person o, Simulation pb)
            {
                double mine = Desire(p, o, pb);
                foreach (var other in pb.Band.Members)
                    if (other != o && CouldPair(p, other) && Desire(p, other, pb) > mine + 0.05) return false;
                return true;
            }
            return Best(a, b, aBand) && Best(b, a, bBand);
        }

        /// <summary>
        /// An occasion to think about leaving one's partner: growing close to someone free, or a fight
        /// with the partner. Weighed against the bond, young children, warmth and how much family matters.
        /// </summary>
        public void ConsiderLeaving(Person p, Person? drawnTo, double strain = 0)
        {
            var partner = p.Partner;
            if (partner == null || !partner.Alive || !Band.Members.Contains(p) || !Band.Members.Contains(partner) || !Grown(p)) return;
            int young = p.Children.Count(c => c.Alive && c.AgeYears(Clock) < 10);
            // A pair bond runs deeper than friendship, and deepens with the years together.
            double years = Math.Min(10, (Clock.Day - p.PairedDay) / (double)SimClock.DaysPerYear);
            double stay = p.GetAffinity(partner) * (1.2 + years * 0.05) + young * 0.3 + p.M(MindTrait.Warmth) * 0.2 * p.W(Drive.Family) - p.GetGrievance(partner) * 0.1
                          - strain;
            // The other has to want them back, as their best choice among those free or nearly so.
            bool free = drawnTo != null && drawnTo.Partner == null && drawnTo.Sex != p.Sex && !p.IsKin(drawnTo) && Grown(drawnTo)
                        && Band.Members.Contains(drawnTo)
                        && !Band.Members.Any(o => o != p && CouldPair(drawnTo, o) && Desire(drawnTo, o, this) > Desire(drawnTo, p, this));
            double go = free ? Desire(p, drawnTo!, this) : 0;
            if (go <= stay) return;
            Separate(p, partner, free ? drawnTo : null);
        }

        void Separate(Person leaver, Person partner, Person? rival)
        {
            leaver.Partner = null; partner.Partner = null;
            // Parting hurts the bond on both sides.
            leaver.AddAffinity(partner, -0.3); partner.AddAffinity(leaver, -0.4);
            partner.AddGrievance(leaver, 3);
            if (rival != null) partner.AddGrievance(rival, 3);
            // The one leaving makes a new hearth (with the new partner if there is one). The young children
            // go with whichever parent is closer to them, pulled by the band's custom; the custom follows
            // what parents actually do.
            var young = leaver.Children.Where(c => c.Alive && c.AgeYears(Clock) < 14 && c.Home == leaver.Home).ToList();
            double leaverClaim = young.Sum(c => c.GetAffinity(leaver)) + (leaver.Sex == Sex.Female ? 1 : -1) * Band.ChildrenFollowMother;
            double partnerClaim = young.Sum(c => c.GetAffinity(partner)) + (partner.Sex == Sex.Female ? 1 : -1) * Band.ChildrenFollowMother;
            var kids = leaverClaim > partnerClaim ? young : new List<Person>();
            if (young.Count > 0)
            {
                bool withMother = (kids.Count > 0) == (leaver.Sex == Sex.Female);
                Band.ChildrenFollowMother += ((withMother ? 1 : -1) - Band.ChildrenFollowMother) * 0.1;
            }
            if (rival != null)
            {
                leaver.Partner = rival; rival.Partner = leaver;
                leaver.PairedDay = rival.PairedDay = Clock.Day;
                NewHousehold(new[] { leaver, rival }.Concat(kids).ToArray());
            }
            else NewHousehold(new[] { leaver }.Concat(kids).ToArray());
            Chronicle.Write(Clock, Importance.Notable, rival != null
                ? $"{leaver.Name} left {partner.Name} for {rival.Name}."
                : $"{leaver.Name} and {partner.Name} parted.");
        }

