            || p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 14 && Home(c))
            || (p.AgeYears(Clock) < 14 && ((p.Mother != null && Home(p.Mother)) || (p.Father != null && Home(p.Father)))));

