import os
os.chdir(r'C:/Users/nars7/Downloads/Ideas and Thoughts/Anthro/Anthro.Sim')
def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:100])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

# Asking works the same for a guest from another camp; what they're given they carry home.
patch('Society.cs', [
("""        public double DoAsk(Person asker, Household hearth, double amount)
        {""",
"""        public double DoAsk(Person asker, Household hearth, double amount, FoodStore? carryHome = null)
        {"""),
("""                MoveFood(hearth, home, give, out _);
                var deed = new Deed { Day = Clock.Day, Actor = giver, Act = Act.Give, Target = asker, Hearth = home, Amount = give, Context = Lesson(Act.Give, RelationTo(giver, asker)) };""",
"""                if (carryHome == null) MoveFood(hearth, home, give, out _);
                else
                {
                    double taken = hearth.Food.Take(give, out double meat);
                    carryHome.AddMeat(meat);
                    carryHome.AddPlants(taken - meat, keeps: true);
                }
                var deed = new Deed { Day = Clock.Day, Actor = giver, Act = Act.Give, Target = asker, Hearth = home, Amount = give, Context = Lesson(Act.Give, RelationTo(giver, asker)) };"""),
])

# Who might go asking another camp: worried about food, by what asking there is expected to bring.
patch('Simulation.cs', [
("""        internal readonly Dictionary<Person, (Simulation band, double pull)> VisitPulls = new Dictionary<Person, (Simulation, double)>();""",
"""        internal readonly Dictionary<Person, (Simulation band, double pull)> VisitPulls = new Dictionary<Person, (Simulation, double)>();
        /// <summary>Those whose visit pull is mostly hunger: they'd go to ask for food.</summary>
        internal readonly HashSet<Person> VisitForFood = new HashSet<Person>();"""),
("""            VisitPulls.Clear();
            var others = Region.Bands.Where(b => b != this && b.Band.Members.Count > 0 && !Region.Together(this, b)).ToList();
            if (others.Count == 0) return;
            foreach (var p in Band.Members)
            {
                if (p.Map.Camps.Count == 0) continue;
                double age = p.AgeYears(Clock);
                if (age < 16 || p.DueDay >= 0 || p.Sickness > 0.2 || p.Current is Visit) continue;
                if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 4)) continue;""",
"""            VisitPulls.Clear();
            VisitForFood.Clear();
            var others = Region.Bands.Where(b => b != this && b.Band.Members.Count > 0 && !Region.Together(this, b)).ToList();
            if (others.Count == 0) return;
            foreach (var p in Band.Members)
            {
                if (p.Map.Camps.Count == 0) continue;
                double age = p.AgeYears(Clock);
                if (age < 16 || p.DueDay >= 0 || p.Sickness > 0.2 || p.Current is Visit) continue;
                // Worry about food: the hearth running short with the land not keeping up. Someone can go
                // asking while another adult minds the little ones.
                var home = HomeOf(p);
                double worry = home.Income >= home.Members.Count * 0.9 || Clock.Day - p.LastVisitDay < 7 ? 0
                    : Inheritance.Clamp01(1 - home.DaysOfFood / Math.Max(6, Math.Min(30, Activities.Decider.LeanDays(this, p))));
                bool tied = p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 4) && !home.Adults(Clock).Any(a => a != p && !(a.Current is Visit));
                if (worry > 0.3 && !tied)
                {
                    Simulation? where = null; double most = 0;
                    foreach (var b in others)
                    {
                        if (!p.Map.Camps.TryGetValue(b.Id, out var at) || Clock.Day - at.day > SimClock.DaysPerYear) continue;
                        double km = WorldMap.Distance(at.x, at.y, Band.CampX, Band.CampY) * WorldMap.CellMeters / 1000;
                        if (km > 25) continue;
                        // Whom they'd be asking: their own people's camps by how they feel about them; another
                        // people's as outsiders. What asking such people has brought is learned, and differs by culture.
                        var rel = b.Tribe == Tribe ? CampRelation(p, b) : Relation.Outsider;
                        double hope = Ties(p, b.Band.Members) * 0.15 + Felt(Expects(p, Act.Ask, rel)) * 0.4 - p.GetBandGrievance(b.Id) * 0.1;
                        double pull = worry * (0.3 + hope) - km * 0.02;
                        if (pull > most) { most = pull; where = b; }
                    }
                    if (where != null) { VisitPulls[p] = (where, most); VisitForFood.Add(p); continue; }
                }
                if (p.Children.Any(c => c.Alive && c.AgeYears(Clock) < 4)) continue;"""),
])

patch('Activities/Decider.cs', [
("""                options.Add(new Option(Verb.Visit, visit.pull, () => new Visit(p, visit.band)));""",
"""                options.Add(new Option(Verb.Visit, visit.pull, () => new Visit(p, visit.band) { ForFood = sim.VisitForFood.Contains(p) }));"""),
])

# The visit: a short one to ask for food, carried home.
patch('Activities/Visit.cs', [
("""        Person? _with;

        public Visit(Person p, Simulation host) : base(p) { Host = host; }""",
"""        Person? _with;
        /// <summary>Gone to ask for food for the family at home.</summary>
        public bool ForFood;
        /// <summary>What they've been given to carry home.</summary>
        readonly FoodStore _pack = new FoodStore();
        readonly System.Collections.Generic.HashSet<Household> _asked = new System.Collections.Generic.HashSet<Household>();

        public Visit(Person p, Simulation host) : base(p) { Host = host; }"""),
("""            _stayHours = sim.Rng.Range(3, 11) * SimClock.HoursPerDay;""",
"""            _stayHours = (ForFood ? sim.Rng.Range(1, 3) : sim.Rng.Range(3, 11)) * SimClock.HoursPerDay;"""),
("""                if (_homeward) { P.X = sim.Band.CampX; P.Y = sim.Band.CampY; Done = true; return; }""",
"""                if (_homeward)
                {
                    P.X = sim.Band.CampX; P.Y = sim.Band.CampY; Done = true;
                    if (_pack.Total > 0 && sim.Band.Members.Contains(P)) Simulation.Unpack(_pack, sim.HomeOf(P).Food);
                    return;
                }"""),
("""            // The hosts' band may have died out, or the guest may be going hungry there.
            if (Host.Extinct || P.Satiety < 0.4 || --_stayHours <= 0) { GoHome(sim); return; }
            if (sim.Clock.IsNight) { P.Fatigue *= 0.9; return; }""",
"""            // The hosts' band may have died out, or the guest may be going hungry there (unless they came
            // hungry, to ask).
            if (Host.Extinct || (!ForFood && P.Satiety < 0.4) || --_stayHours <= 0) { GoHome(sim); return; }
            if (sim.Clock.IsNight) { P.Fatigue *= 0.9; return; }

            // Asking the hearths here for food to take home, one at a time, fondest first; each answers by
            // their own lights (and their people's ways with guests). Once their hands are full, or
            // nobody's left to ask, they set off home.
            if (ForFood && sim.Clock.Hour % 3 == 0)
            {
                double carry = Physiology.CarryCapacity(P, P.AgeYears(sim.Clock));
                var family = sim.HomeOf(P);
                double want = Math.Min(carry - _pack.Total, family.Members.Count * 0.9 * 7);
                var hearth = Host.Band.Households.Where(h => !_asked.Contains(h) && h.Food.Total > 1)
                    .OrderByDescending(h => h.Members.Sum(m => m.GetAffinity(P))).FirstOrDefault();
                if (want <= 0.5 || hearth == null) { _stayHours = Math.Min(_stayHours, 1); }
                else
                {
                    _asked.Add(hearth);
                    Host.DoAsk(P, hearth, want, _pack);
                    Step = _pack.Total > 0 ? $"carrying food given by the {Host.Band.Name} band" : $"asking the {Host.Band.Name} band for food";
                }
            }"""),
])

patch('Social.cs', [
("""        static void MoveFood(FoodStore from, FoodStore to)""",
"""        /// <summary>Food carried home goes into the family's store.</summary>
        internal static void Unpack(FoodStore pack, FoodStore home) => MoveFood(pack, home);

        static void MoveFood(FoodStore from, FoodStore to)"""),
])
print('ok')

